INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (1, 'Thermo Fisher Scientific', 'Thermo Scientific, Fisher Scientific, Invitrogen, Applied Biosystems, Gibco, Patheon, PPD, Phadia, Oxoid, Olink', 'Waltham, Massachusetts', 'USA', '', 'Public (NYSE: TMO)', 1956, 'https://www.thermofisher.com', 'Diversified analytical & life-science instruments', 125000, 2025, 'FY2025 Form 10-K: ''As of December 31, 2025, we employed approximately 125,000 colleagues globally'' (~59,000 Americas, ~44,000 EMEA, ~22,000 Asia-Pacific).', 'USD 44.56 billion', 44560, 'FY2025', 'company', 'FY2025 revenue USD 44.56 billion (+3.9% vs 2024) per StockAnalysis / AmericanCompanies summaries of the SEC 10-K; the 10-K itself (sec.gov link in sources) could not be opened in-session.', 'reported', 'subsidiary', '[אימות עדכניות 10/2026] Re-verified on live pages: Rhenium (Applied Biosystems/Invitrogen/Thermo Scientific reagent, dPCR and centrifuge pages), Bargal (Orbitrap MS, combustion IC, ICP-MS/FTIR application notes), Danyel (Olink brand page) and Gamidor (Phadia ImmunoCAP/EliA pages) all currently market Thermo Fisher lines, and thermofisher.com''s Phenom desktop-SEM distributor page names Thermo Fisher Integrated Solutions as the Israel contact. thermofisher.com additionally lists three Israeli partners for industrial/portable lines (Iner-Tech, R.B.M., Madid), added as new. The Kiryat Shmona manufacturing site and the Airport City EM service location were not re-found in snippets (a Thermo Fisher careers page only confirms jobs in Israel generally); Gamidor''s microbiology scope (2025-26 letter) was not visible on its live pages, which show allergy/autoimmune diagnostics. Established from search-result evidence only (WebFetch and curl were blocked by the environment''s network policy, so manufacturer and distributor pages could not be opened). Searches run: ''"Thermo Fisher" Israel distributor'', ''"Thermo Fisher Scientific" Israel office Ltd'', ''"Thermo Fisher" ישראל נציג יבואן'', ''Rhenium Thermo Scientific Israel distributor'', ''Invitrogen Applied Biosystems Gibco Israel distributor'', ''"Thermo Fisher Integrated Solutions Israel"'', ''Bargal Analytical Instruments ... Thermo Scientific''. Picture: Thermo Fisher has its OWN Israeli presence (Thermo Fisher Israel Ltd. site in Kiryat Shmona with Israeli ISO certificates; an EM service location in Airport City, Lod; and a newly formed ''Thermo Fisher Integrated Solutions Israel'' subsidiary in Ra''anana that is hiring key-account managers and building a field-service team - i.e. a move toward direct sales for life-science products), PLUS division-specific Israeli distributors: Gamidor Diagnostics (non-exclusive distributor letter valid to Mar 2026, likely diagnostics/microbiology), Danyel Biotech (Olink), Rhenium (Life Technologies brands since 2011 - stale, may have been superseded by the new direct subsidiary) and Bargal (chromatography, 2018-2019 letter - stale). Fisher Scientific channel / Phadia (ImmunoCAP) / Thermo Scientific lab-equipment distributors in Israel were NOT established (the Phadia-locations page exists but could not be read). The exact registered names of the Israeli entities are unconfirmed (job ads say ''Thermo Fisher Integrated Solutions Israel'' / ''...Integrated Solutions Ltd'').', 'medium', 'Size: official 10-K figures (high). Israel: own-subsidiary evidence rests on Thermo Fisher-hosted ISO certificates, a Thermo Fisher service-locations page and multiple Thermo Fisher job postings; distributor evidence is partly stale (Rhenium 2011, Bargal 2018-19) or scope-ambiguous (Gamidor 2025-26 tender letter). Manufacturer/distributor pages could not be opened to confirm.', 'company', 'verified', 2026, 'confirmed_current', '+972 73 256 0860', '', '', '', 'Israel office — not found on thermofisher.com (2 searches); the only phone is an unverified aggregator listing (startupim, confidence 69/100). Thermo Fisher job listings place staff in Tel Aviv. Olink (a Thermo Fisher company) names Danyel Biotech Ltd., HaMada St. 8, Rehovot 7670308, +972 8 966 066 (as shown) as its Israeli distributor. Verify before use.');
