INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (2, 'Agilent Technologies', 'Agilent, BioTek, Dako, Agilent CrossLab', 'Santa Clara, California', 'USA', '', 'Public (NYSE: A)', 1999, 'https://www.agilent.com', 'Diversified analytical & life-science instruments', 18000, 2024, 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2024 Form 10-K: approximately 18,000 employees (FY2025 10-K figure not checked).', 'USD 6.51 billion', 6510, 'FY2024 (ended 31 Oct 2024)', 'company', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2025 (ended 31 Oct 2025) revenue was reported around USD 6.9-7.0 billion but is not verified here.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Agilent''s own live Israel contact page (agilent.com/en/contact-us/israel) still lists Eldan Electronic Instruments Ltd., Petach Tikva, as its authorized distributor with phone and e-mail; a second Agilent partner page gives an Eldan contact address. A search restricted to eldan.biz returned only SEC filings (search-engine quirk), but Eldan pages seen in other searches (2014 ILANIT listing, 2017 Seahorse users meeting) are consistent. No direct Agilent office in Israel surfaced. Agilent''s own Israel contact page lists Eldan Electronic Instruments (Kiryat Gat / Petah Tikva, Neopharm group) as its authorised distributor; Eldan''s site says it has represented Agilent for over four decades. Whether Agilent also has a direct office for genomics/cell analysis (BioTek) remains to be checked.', 'medium', 'Israel: one official-source entity supplied by the brief, not re-verified and not checked for completeness. Low: identity/products from model knowledge; size figures recalled from published reports but not verified in-session; Israeli presence not researched (search budget exhausted, WebFetch/curl blocked). Needs a follow-up research run.', 'company', 'verified', 2026, 'confirmed_current', '+1 408-345-8886 / +1 877-424-4536', 'contact_us@agilent.com', '5301 Stevens Creek Blvd., Santa Clara, CA 95051, USA', '', 'HQ (Agilent site footer); no Israel/EMEA contact shown.');
