INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, evidence_year, status, source) VALUES (13, 3, 'Mercury Scientific & Industrial Products Ltd. (Gadot group)', 'מרקורי מוצרי מדע ותעשייה (גדות מרקורי)', 'distributor', 'Merck Milli-Q laboratory water-purification systems (IX, IQ 7000, HX, CLX, SQ2 series) - live product pages describe Mercury as Merck''s exclusive Israeli distributor; Millipore filtration/MQuant lines per prior evidence', 'https://www.mercury-ltd.co.il', '+972 3-938-7164', '', '12 Ha''avoda St., P.O. Box 159, Rosh Ha''ayin', 'https://eng.mercury-ltd.co.il/about_us', 2026, 'current', 'https://eng.mercury-ltd.co.il/lab_water_purification');
