INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (5, 'Bruker Corporation', 'Bruker BioSpin, Bruker Daltonics, Bruker AXS, Bruker Nano, Bruker Optics, Bruker Cellular Analysis, NanoString, ELITechGroup', 'Billerica, Massachusetts', 'USA', '', 'Public (Nasdaq: BRKR)', 1960, 'https://www.bruker.com', 'Diversified analytical & life-science instruments', 9900, 2024, 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). Approximately 9,900 employees (2024 10-K); 2025 figure not checked.', 'USD 3.37 billion', 3366, 'FY2024', 'company', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2024 revenue USD 3,366 million; FY2025 (~USD 3.4-3.5 billion) not verified.', 'reported', 'subsidiary', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Lapidot Group''s live business-partners page (lapidot.com/en/partners) still lists Bruker, confirming the distributor relationship from the distributor''s side. Bruker''s own entities (Bruker Scientific Israel, Rehovot; Gedera MS office) and New Technology (NT) Ltd. were not re-searched in this round (budget); their prior evidence is Bruker''s own support pages dated 2025-2026, so they are carried at 2025 without fresh confirmation. One scope-clarification search (Bruker + Israel + NMR/MS/AXS/Lapidot). Bruker''s own Israel support page (English, Japanese and Spanish versions, 2025-2026) names Lapidot Medical Import and Marketing Ltd., Caesarea Industrial Park, as the Israel contact and says mass-spectrometry questions go to Bruker''s office in Gedera, Israel. No division-specific (NMR/AXS/Nano/microCT) partner listings appeared, so Lapidot appears to be the general Israeli partner while MS is handled by Bruker''s own local office; the Gedera entity''s legal name and the exact split of duties were not visible and Lapidot''s own site was not checked. Bruker''s own office page also lists Bruker Scientific Israel Ltd. (Rehovot) with sales/support numbers and names New Technology (Ramat Gan) and Lapidot (Caesarea) as distributors.', 'high', 'Both Israeli entities come from Bruker''s official support page; division-level scope and the Gedera entity name remain unconfirmed.', 'company', 'partial', 2026, 'confirmed_current', '+972 8 947 7705', 'bsis@bruker.com', '5 Golda Me''ir St., Science Park, P.O. Box 2445, Rehovot 76123, Israel', 'https://www.bruker.com/en/services/support/india-middleeast-africa/israel-rehovot.html', 'Israel office (Bruker Scientific Israel Ltd., Rehovot; sales line/email shown for X-ray products; support +972 8 947 7704, service.baxs.ime@bruker.com; Magnetic Resonance/Preclinical Imaging at 1st Yaacov Perry St., Rehovot). AFM/mechanical testing via distributor New Technology, 11 Tuval St., 7th Floor, Ramat Gan 52522, +972 3 679 2000; microbiology/diagnostics via Lapidot Medical, 8 Hashita St., Caesarea Industrial Park 3088900; mass spectrometry: Bruker office in Gedera (no address/phone shown).');
