INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (6, 'Shimadzu Corporation', 'Shimadzu Scientific Instruments, Shimadzu Europa, Shimadzu Analytical & Measuring Instruments', 'Kyoto', 'Japan', '', 'Public (TSE: 7701)', 1875, 'https://www.shimadzu.com', 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 14600, 2025, 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). Consolidated group headcount approx. 14,600 as of 31 Mar 2025 (approximate).', 'JPY 511.9 billion', 3430, 'FY ending Mar-2025', 'company', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). Consolidated net sales ~JPY 511.9 billion for FY2024 (ended 31 Mar 2025); FY ending Mar-2026 not verified. Converted at JPY 0.0067.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Agentek''s live site still has a dedicated Shimadzu representative page, lists Shimadzu on its vendors page and carries current Shimadzu product pages (i-Series LC, GCMS-TQ 8040 NX, TOC-L). A search restricted to shimadzu.com/shimadzu.eu did not expose the Israel entry of Shimadzu''s distributor locator, so manufacturer-side confirmation and any separate partner for medical/X-ray or balances remain unverified. Searched ''Shimadzu'' Israel distributor/representative/נציג/יבואן, then restricted to Israeli distributor domains and to shimadzu.com. Agentek''s own site has a dedicated Shimadzu representative page, lists Shimadzu on its vendors page and carries current Shimadzu product pages (i-Series LC, LCMS-9050, Nexis GC-2060, ALTRACE XRF). Shimadzu''s global contact-search page lists Israel among its Middle East & Africa countries but the local partner''s name was not visible in the snippets, so manufacturer-side confirmation and exclusivity (and any separate partner for medical/X-ray or balances) remain unverified; no Shimadzu Israeli subsidiary was found. Agentek''s own vendors page (agentek.co.il/vendors) lists the brand among the manufacturers it represents in Israel (seen in a search excerpt; the manufacturer''s own distributor page was not opened).', 'medium', 'Distributor''s own brand page with current products; not confirmed on Shimadzu''s site.', 'company', 'verified', 2026, 'confirmed_current', '+81 75 823 1111', '', '1 Nishinokyo Kuwabara-cho, Nakagyo-ku, Kyoto 604-8511, Japan', '', 'HQ (official corporate profile 2025-26); no general email shown; US subsidiary Shimadzu Scientific Instruments, Columbia, MD: +1 410-381-1222 / +1 800-477-1227.');
