INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (7, 'Mettler-Toledo International', 'Mettler Toledo, Rainin, Ohaus, Thornton, Safeline, Hi-Speed', 'Columbus, Ohio (operational HQ Greifensee, Switzerland)', 'USA', '', 'Public (NYSE: MTD)', 1945, 'https://www.mt.com', 'Lab balances & weighing', 17000, 2024, 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). Approximately 17,000 employees (2024 10-K).', 'USD 3.87 billion', 3872, 'FY2024', 'company', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2024 net sales USD 3,872 million; FY2025 (~USD 3.9-4.0 billion) not verified.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Agentek''s live Mettler Toledo representative page and product pages (balances, Rainin pipettes, CHRONECT XPR, EasyViewer, roller scales, throat metal detector) confirm it as the current lab-weighing/pipetting channel; note Agentek also lists Mettler product-inspection and industrial-scale items, overlapping the scope mt.com assigns to Dinco. Modcon and Dinco were not re-searched (prior evidence is Mettler-Toledo''s own mt.com/il page). No Israeli Mettler-Toledo subsidiary surfaced. Searched Mettler-Toledo Israel distributor/נציג/יבואן, Israeli distributor domains, and mt.com. Mettler-Toledo''s own Israel page (mt.com/il) lists three partner companies instead of a direct office: Agentek (1987) Ltd. for laboratory weighing, Modcon Systems Ltd. for process analytics and Dinco Ltd. for product inspection. Agentek''s site independently confirms it with a Mettler Toledo representative page, a news item that it distributes Mettler-Toledo Rainin pipettes, and balance/titration/scale product pages. No Mettler-Toledo Israeli subsidiary was found; phone numbers and the exact scope split were taken from search snippets and not re-checked on the live page. Agentek''s own vendors page (agentek.co.il/vendors) lists the brand among the manufacturers it represents in Israel (seen in a search excerpt; the manufacturer''s own distributor page was not opened).', 'high', 'Manufacturer''s own Israel page plus the distributor''s own site agree.', 'company', 'verified', 2026, 'confirmed_current', '+1 614-438-4511', '', '1900 Polaris Parkway, Columbus, OH 43240, USA', '', 'HQ (Columbus, OH; address also on GlobalData profile). Operational HQ: Im Langacher 44, CH-8606 Greifensee, Switzerland — +41 44 944 22 11 (2014 annual report) / +41 44 944 45 45 (American Pharmaceutical Review). Phone numbers come from a 2014 report and directories — verify. No general email shown.');
