INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (8, 'Sartorius AG', 'Sartorius Stedim Biotech, Sartorius Lab Instruments, Octet (ex-ForteBio), BIA Separations, Biological Industries', 'Göttingen', 'Germany', '', 'Public (FWB: SRT / SRT3)', 1870, 'https://www.sartorius.com', 'Bioprocess & filtration', 13500, 2024, 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). Group headcount approx. 13,500 at end-2024 (approximate).', 'EUR 3.38 billion', 3719, 'FY2024', 'company', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2024 sales revenue EUR 3,381 million; FY2025 (~EUR 3.5-3.6 billion) not verified. Converted at EUR 1.10.', 'reported', 'subsidiary', '[אימות עדכניות 10/2026] Sartorius'' own live ''Find your local contact'' page lists Sartorius Israel at Kibbutz Beit Haemek with phone and e-mail, the list-of-companies page and Beit Haemek site news/blog pages confirm the subsidiary. Labotal''s live Hebrew balance guides state it exclusively represents Sartorius in Israel (Cubis II balances, pipettes). Both channels re-confirmed on live pages. Searched Sartorius Israel/Beit HaEmek generically, Sartorius on Israeli distributor domains, sartorius.com and labotal.co.il. Sartorius'' ''local contact'' page lists Sartorius Israel at Kibbutz Beit Haemek 2511500, its list of companies includes Sartorius Israel Ltd., press releases confirm the majority acquisition of Biological Industries (2019) and the June 2021 opening of the Beit Haemek cell-culture-media plant, and a Sartorius job ad for a home-office sales representative in Israel shows in-country sales staff. Lab products: Labotal describes itself on its own site as the exclusive Sartorius representative in Israel for weighing (Cubis II balances) and lists Sartorius pipettes; the filtration channel was not seen. Caveat: a Sartorius Stedim Biotech financial-statement note refers to ''Sartorius Israel Ltd. (51%)'' as not consolidated for materiality, so the legal entity may be a small, partly-owned company distinct from the Beit Haemek production business.', 'high', 'Israeli entity confirmed on manufacturer''s contact and subsidiaries pages; Labotal''s exclusivity for balances is self-reported.', 'company', 'verified', 2026, 'confirmed_current', '+972 4 996 0595', '', 'Kibbutz Beit Haemek 2511500, Israel', 'https://www.sartorius.com/en/contact-us/local-contact', 'Israel office (Sartorius Israel, per third-party directory — fax +972 4 996 0043; not confirmed on sartorius.com, whose newsroom mentions an upgraded facility/new site for cell culture media production in Israel). HQ: Sartorius Campus, Otto-Brenner-Str. 20, 37079 Göttingen, Germany, +49 551 3080.');
