INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (9, 'Revvity', 'formerly PerkinElmer, Inc. (renamed May 2023); EUROIMMUN, BioLegend, Horizon Discovery, Nexcelom, Oxford Immunotec, Cisbio/HTRF, Dharmacon, Omni', 'Waltham, Massachusetts', 'USA', '', 'Public (NYSE: RVTY)', 1937, 'https://www.revvity.com', 'Life-science instruments & reagents', 11000, 2025, '11,000+ employees per Revvity 2025 Corporate Fact Sheet (March 2025)', 'USD 2.76 billion', 2755, 'FY2024', 'company', 'Figure from model knowledge of the company''s published report; could not be re-verified against a source in this session (search budget exhausted, network blocked). FY2024 revenue USD 2,755 million; FY2025 (~USD 2.8 billion) not verified.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Gamidor''s live genetics page (represents Revvity in prenatal screening since 1984; neonatal screening for the national lab) and Enco''s live catalogue/news pages (Revvity reagents, plates and automatic cell counting) re-confirm both channels. No Revvity Israeli subsidiary was found in earlier rounds and nothing new contradicts that. Searched Revvity Israel distributor/נציג/יבואן, Israeli distributor domains (Revvity OR PerkinElmer), revvity.com and a ''Revvity Israel'' entity search. No Revvity Israeli subsidiary or office was found: revvity.com''s office/distributor listing and the 2023 SEC Exhibit 21 subsidiary list show no Israel entity, and the 2013 ''PerkinElmer establishes direct operations in Israel'' release (now on ir.revvity.com) refers to the Ra''anana office that today is listed by PerkinElmer (the analytical company), not Revvity. Gamidor''s own site says it represents Revvity for prenatal screening and Enco''s catalogue sells Revvity plates/reagents; no Israeli partner was found for Revvity life-science instruments (EnVision, Opera Phenix) or for newborn-screening instruments, which may be sold directly from abroad or via an unidentified channel. Enco''s suppliers page lists Revvity and its catalogue carries Revvity screening reagents.', 'medium', 'Distributor-site evidence for diagnostics reagents and consumables; coverage of instruments and newborn screening unverified; no manufacturer-side confirmation.', 'company', 'verified', 2026, 'confirmed_current', '+1 781-663-6900', '', '940 Winter Street, Waltham, MA 02451, USA', '', 'HQ (address from official 2024 corporate fact sheet); phone from a third-party directory (Prospeo) — other directories list +1 781-462-5126 and +1 781-663-5791; no general email shown.');
