INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (10, 'PerkinElmer (New Mountain Capital)', 'PerkinElmer analytical, enterprise & food businesses carved out of the former PerkinElmer (now Revvity) in 2023; NexION, Avio, Spectrum, Lambda, Pyris, OneSource', 'Shelton, Connecticut', 'USA', 'New Mountain Capital', 'Private equity (New Mountain Capital, since March 2023)', 1937, 'https://www.perkinelmer.com', 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 6000, 2022, 'STALE: ~6,000 employees was the headcount of the Applied, Food & Enterprise Services business at the time of the Aug-2022 carve-out to New Mountain Capital (PerkinElmer press release, reported by GenomeWeb/360Dx). No 2024/2025 headcount or revenue found from an official or reputable source in this round; sale consideration was USD 2.45 billion (USD 2.30 billion at closing, Mar-2023). Headcount is the ~6,000 cited at the Aug-2022 carve-out from PerkinElmer (stale); no newer official figure.', 'USD 1.3 billion (estimate)', 1300, 'FY2022 (at carve-out)', 'estimate', 'No 2024/2025 revenue figure found from an official or reputable source; aggregator figures ignored.', 'mixed', 'subsidiary', '[אימות עדכניות 10/2026] perkinelmer.com''s live office-locations page (location=IL) and its ''PerkinElmer Israel Ltd'' node still list the Ra''anana office with address and phone, confirming the direct subsidiary. ISI Israel Scientific Instruments could not be re-confirmed from its own domain (search returned only SEC filings), so it is kept on the prior perkinelmer.com evidence. Searched PerkinElmer Israel distributor/נציג/יבואן (ICP/GC/FTIR), perkinelmer.com office/distributor pages and a 2024-2026 ''PerkinElmer Israel Ltd'' news search. PerkinElmer set up direct sales/service operations in Israel in August 2013 (press release; GM Aaron Geist named in 2015) and perkinelmer.com currently lists a PerkinElmer Israel office/PerkinElmer Israel Ltd. in Ra''anana plus ISI Israel Scientific Instruments Ltd. (Petach Tikva) as an Israeli partner for food testing. After the 2023 split the Israel entity stayed with the analytical company (now New Mountain Capital-owned PerkinElmer) rather than Revvity; no 2024-2026 Israel-specific news was found, so current staffing/scope of the Ra''anana office rests on the manufacturer''s current listing only.', 'high', 'Manufacturer''s own office-locations page names the Israeli subsidiary and partner; no recent independent confirmation.', 'company', 'verified', 2026, 'confirmed_current', '1700-500-512 (Israel domestic number)', 'cc.israel@perkinelmer.com', '', '', 'Israel office (PerkinElmer Israel Ltd.; ''headquartered near Tel Aviv'', no street address shown); fax 1700-555-915; details from a 2013 press release and a 2017-18 catalog — dated; the life-sciences business became Revvity in 2023, so verify which entity this contact now belongs to.');
