INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (11, 'Bio-Rad Laboratories', 'Bio-Rad; DiaMed (immunohematology)', 'Hercules, California', 'USA', '', 'Public (NYSE: BIO)', 1952, 'https://www.bio-rad.com', 'Life-science instruments & reagents', 7450, 2025, 'Third-party aggregator figure (company profiles citing FY2025 data); the FY2025 10-K could not be opened in this session (fetch tool failure) and aggregators range from ~7,450 to ~8,300. Treat as approximate.', 'USD 2.58 billion', 2580, 'FY2025', 'company', 'EDGAR-derived aggregator figure (edgar.tools: USD 2.58B for FY ending 2025-12-31); another summary says USD 2.55B. 10-K itself not opened. Two segments: Life Science and Clinical Diagnostics.', 'mixed', 'subsidiary', '[אימות עדכניות 10/2026] Bio-Rad''s own site re-confirms the Israeli subsidiary: the Israel trading-terms document names Bio-Rad Laboratories Ltd., 14 Homa Street, Rishon LeZion; the quality-certificates page covers an ISO 9001:2015 certificate for the Rishon LeZion site (sales, distribution and after-sales service; expiring 12 Nov 2026); and careers.bio-rad.com has a dedicated Israel page. Bio-Rad Haifa Ltd. (R&D) has only the 2006 acquisition/SEC-exhibit evidence. Own subsidiary confirmed. Bio-Rad''s careers site has a dedicated Israel page and job postings under ''Bio-Rad Israel Ltd'' with work location ''Bio-Rad Laboratories Ltd, Rishon Le Zion, Israel, 75655''. Bio-Rad''s SEC Exhibit 21.1 (FY2019 and FY2021 10-Ks) lists ''Bio-Rad Laboratories (Rishon), Inc.'' (f/k/a Bio-Rad Laboratories (Israel), Inc., California jurisdiction) and ''Bio-Rad Haifa Ltd.'' (Israel). A company directory (startupim) gives the Rishon LeZion address as 14 HaHoma St. and says the Israeli sales branch was established in 1991; Bio-Rad Haifa is the R&D centre created from the 2006 ProteOptics acquisition. Sources conflict on the exact legal form of the Rishon entity (Israeli ''Ltd'' vs California ''Inc.''). Direct sales via the own subsidiary is the channel; no independent distributor surfaced. Limitation: bio-rad.com contact page could not be opened (fetch tool failure) and the search budget ran out before a domain-restricted check.', 'medium', 'Israeli subsidiary is well supported (own careers site + SEC subsidiary exhibit). Size figures come from aggregators, not the 10-K itself, because page fetching failed in this session.', 'company', 'verified', 2026, 'confirmed_current', '', '', 'Hahoma Street 14, Rishon LeZion, Israel', 'https://www.bio-rad.com/en-il/contact-us', 'Israel office (Bio-Rad Laboratories Ltd., Rishon LeZion 75655 per Bio-Rad careers page; street address from third-party directories, unverified); Haifa R&D site (Bio-Rad Haifa, ex-ProteOptics) at Netiv HaOr; no phone/email shown — the official Israel contact page should have them.');
