INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (13, 'Eppendorf SE', 'Eppendorf AG (until 2021); New Brunswick (brand)', 'Hamburg', 'Germany', '', 'Private (family-owned)', 1945, 'https://www.eppendorf.com', 'Liquid handling & lab automation', 4125, 2025, 'Annual average full-time equivalents 2025 per Eppendorf Group Annual Report 2025 key-figures table (2024: 4,658 FTE).', 'EUR 924 million', 1016, 'FY2025', 'company', 'Eppendorf Group consolidated revenue EUR 924.0M in FY2025 (prior year EUR 980M, -5.7%); EBIT EUR 95.6M. Converted at EUR 1.10.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Lumitron''s live site carries a broad Eppendorf range (centrifuges, pipettes, BioFlo/BioBLU bioreactors, CellXpert incubator shakers, Eporator, micromanipulators) with hosted Eppendorf brochures, which replaces the earlier LinkedIn-only evidence. Eppendorf''s own site lists Israel in its country selector and says the Dubai regional company (Eppendorf Middle East and Africa FZ-LLC) works through local partners, but its distributor overview''s Israel entry was not visible in snippets, so manufacturer-side naming is still missing. Evidence is indirect: a Hebrew LinkedIn post (Nili Krool, Israel) announcing the Israeli launch (6 March) of the Eppendorf SpinPro 6 R centrifuge directs enquiries to Lumitron (לומיטרון), described as part of the Comtel Technologies & Engineering group (קומטל) and an importer of laboratory equipment and consumables - implying Lumitron markets Eppendorf in Israel, although the post does not state the distributorship explicitly. Eppendorf''s corporate site says it has subsidiaries in 33 countries and is represented elsewhere by distribution partners; no ''Eppendorf Israel'' subsidiary surfaced. Searched ''Eppendorf Israel distributor'' and ''אפנדורף Eppendorf נציג בישראל''. The eppendorf.com distributor/contact page and Lumitron''s own site could not be opened (fetch failure; search budget exhausted), so this needs confirmation.', 'medium', 'Size figures are official (Annual Report 2025). The Israeli distributor attribution rests on a single Hebrew LinkedIn post and was not confirmed on Eppendorf''s or Lumitron''s own site.', 'company', 'verified', 2026, 'confirmed_current', '+49 40 53801-0', 'eppendorf@eppendorf.de', 'Barkhausenweg 1, 22339 Hamburg, Germany', '', 'HQ (official imprint); fax +49 40 53801-556; US: Eppendorf North America +1 800-645-3050.');
