INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (15, 'Illumina', 'Solexa (legacy); Emedgene (Israeli subsidiary)', 'San Diego, California', 'USA', '', 'Public (NASDAQ: ILMN)', 1998, 'https://www.illumina.com', 'Genomics / sequencing', 8600, 2025, 'FY2025 10-K: ~8,600 full-time employees as of 28 Dec 2025 (plus ~50 part-time and ~1,430 contingent workers); 8,970 a year earlier. Regional split: ~4,740 Americas, ~1,280 Europe, ~2,350 AMEA, ~290 Greater China.', 'USD 4.34 billion', 4343, 'FY2025', 'company', 'Third-party summary of the FY2025 10-K: revenue USD 4,343M, down 1% from USD 4,372M in FY2024 (~74% consumables, 11% instruments, 15% services). Income-statement page of the 10-K not opened directly.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Illumina''s own live ''Find an Illumina Distributor'' page lists Danyel Biotech Ltd., Rehovot, for Israel and the Palestinian Territories with address, phone and e-mail, and Danyel''s live site has an Illumina brand page - the 2020 press-release evidence is superseded. Illumina''s locations page lists the Illumina Israel Excellence Center in Tel Aviv (manufacturing/R&D), confirming the own R&D entity. Distributor: Danyel Biotech (Rehovot, founded 1998, part of the Gamida for Life group) is described in a January 2020 Saphetor/VarSome press release as ''a leading distributor providing innovative solutions such as Illumina, ArcherDx etc.'' in Israel. That evidence is from 2020 and could not be re-verified on danyel.co.il or illumina.com''s distributor page (fetch failure; search budget exhausted). Own entity: Illumina runs an Israeli R&D/AI centre of excellence in Tel Aviv (~30 employees, headed by Einat Metzer) built on Emedgene, ''an Illumina company'' (acquired 2022), per Calcalist and Israeli job listings; a third-party profile dates Illumina''s Israeli presence to January 2022. No evidence was found that Illumina sells instruments or consumables directly in Israel, so the commercial channel is recorded as distributor with the own entity as R&D only. Searched ''Illumina Israel distributor Danyel Biotech'' and ''אילומינה Illumina ישראל נציג יבואן''.', 'medium', 'Headcount is from the FY2025 10-K; revenue from a 10-K summary. Danyel distributorship rests on a 2020 third-party press release and was not re-confirmed on either company''s site.', 'company', 'verified', 2026, 'confirmed_current', '', '', 'Yigal Alon St 114, Tel Aviv-Yafo, Israel', '', 'Israel office (address from third-party aggregators, unverified; Illumina set up an AI genome-analysis Excellence Center in Israel in 2022); no phone/email shown; illumina.com locations page lists no Israel office.');
