INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (17, 'Cytiva (Danaher)', 'GE Healthcare Life Sciences (former); Amersham; Whatman; HyClone; Pall life sciences (merged 2023)', 'Marlborough, Massachusetts', 'USA', 'Danaher Corporation', 'Subsidiary of Danaher Corporation (public, NYSE: DHR)', 2020, 'https://www.cytivalifesciences.com', 'Bioprocess & filtration', 16000, 2025, 'Cytiva states 16,000+ associates after absorbing Pall''s life-science business (2023). Figures recalled from company statements / filings and not re-verified online in this session.', 'USD 7.3 billion (Danaher Biotechnology segment)', 7300, 'FY2025', 'segment', 'Danaher Biotechnology segment (Cytiva incl. Pall life sciences) ~USD 7.3B FY2025; Cytiva alone not disclosed.', 'mixed', 'distributor', '[אימות עדכניות 10/2026] Danyel Biotech''s live site carries a ''Biacore (Cytiva)'' brand page (alongside its Cytiva page from the prior round), confirming Danyel as a current Cytiva channel. Cytiva''s own find-a-distributor page lists Israel as a country option but the partner name is not in snippets, and Cytiva''s contracting-entity table assigns Israel to Pall Austria Filter Ges.m.b.H. Lifegene (Whatman) was not re-searched. Searched generic queries (incl. ÄKTA/Whatman/Amersham), 27 Israeli distributor domains, cytivalifesciences.com and a Whatman-specific query. Danyel Biotech''s own site has a Cytiva brand page (ÄKTA pure chromatography; Biacore listed as a Cytiva supplier), so Danyel is a current Israeli channel. Cytiva''s ''find a distributor'' page lists Israel as a selectable country but the partner name was not visible in snippets, and Cytiva''s terms document lists Israel under its international contracting entity Pall Austria Filter Ges.m.b.H., i.e. direct contracts are also written from abroad. The 2009 Rhenium-for-Whatman listing could not be re-confirmed and no current Israeli Whatman/Amersham channel was found. Lifegene''s catalogue carries Whatman (Cytiva) filtration products; Danyel Biotech has Cytiva brand pages for ÄKTA and Biacore.', 'medium', 'Distributor evidence is the distributor''s own brand page; manufacturer-side naming of the Israeli partner was not visible and the scope across Cytiva''s many brands is unclear.', 'estimate', 'verified', 2026, 'confirmed_current', '+1 800-526-3593', '', '100 Results Way, Marlborough, MA, USA', '', 'HQ (trade-show exhibitor listing; ZIP shown inconsistently as 08855-1327 in results); one directory lists 800 Centennial Ave Bldg 5-4, Piscataway, NJ 08854 and +1 866-321-7186; no general email shown.');
