INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (18, 'Leica Microsystems (Danaher)', 'Leica Microsystems GmbH; Leitz (heritage)', 'Wetzlar', 'Germany', 'Danaher Corporation', 'Subsidiary of Danaher Corporation (public, NYSE: DHR)', 1849, 'https://www.leica-microsystems.com', 'Light microscopy & imaging', 3500, 2025, 'Approximate Leica Microsystems headcount (company statements cite several thousand employees); parent Danaher ~60,000. Figures recalled from company statements / filings and not re-verified online in this session.', 'USD 7.3 billion (Danaher Life Sciences segment)', 7300, 'FY2025', 'segment', 'Danaher Life Sciences segment ~USD 7.3B FY2025 (Leica Microsystems, SCIEX, Molecular Devices, Beckman LS, Abcam, IDT, Aldevron…); Leica alone not disclosed.', 'mixed', 'distributor', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Lapidot Group''s live partners and eye-surgery pages still present Leica surgical microscopes, so the medical-division channel is current. For research microscopes the only evidence remains the 2009 IPS listing naming Rhenium: a search restricted to rhenium.co.il returned no Leica page and a general search found nothing newer (Leica''s own site says it works through sales organisations in 20 countries and distribution partners elsewhere, without naming Israel). The research-microscope channel is therefore unverified and may have changed. Searched generic queries, 27 Israeli distributor domains, leica-microsystems.com, lapidot.com and rhenium.co.il. Lapidot Group''s own partner and eye-surgery pages show it markets Leica surgical microscopes in Israel, i.e. the Leica Microsystems medical division. For research microscopes (confocal, stereo, cryo-EM sample prep) the only evidence remains the 2009 Israel Physical Society listing naming Rhenium as exclusive representative; a 2026 search restricted to rhenium.co.il returned nothing, and Leica''s site shows no Israeli office (country selector only, ''contact your local representative''). The research-microscope channel is therefore unconfirmed and the Rhenium entry is stale.', 'medium', 'Surgical-microscope channel verified on the distributor''s own site; research-microscope channel rests on a 2009 listing and could not be re-verified.', 'estimate', 'partial', 2026, 'confirmed_current', '+49 6441 29-0', '', 'Ernst-Leitz-Strasse 17-37, 35578 Wetzlar, Germany', '', 'HQ (official imprint; fax +49 6441 29-2599); no general email shown — a Spectaris member listing gives corporate.communications@leica-microsystems.com (+49 6441 29 2201 / 2630).');
