INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (20, 'Molecular Devices (Danaher)', 'Molecular Devices, LLC; Axon Instruments (patch clamp)', 'San Jose, California', 'USA', 'Danaher Corporation', 'Subsidiary of Danaher Corporation (public, NYSE: DHR)', 1983, 'https://www.moleculardevices.com', 'Microplate readers & detection', 1000, 2025, 'Approximate Molecular Devices headcount (~1,000); parent Danaher ~60,000. Figures recalled from company statements / filings and not re-verified online in this session.', 'USD 7.3 billion (Danaher Life Sciences segment)', 7300, 'FY2025', 'segment', 'Danaher Life Sciences segment ~USD 7.3B FY2025; Molecular Devices alone not disclosed.', 'mixed', 'distributor', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] A search restricted to Israeli distributor domains returned only Eisenberg Bros. pages for Molecular Devices, but now three product lines (FLIPR Penta, GenePix microarray systems, GxP compliance solutions for microplate readers) on its live site, which upgrades Eisenberg Bros. from candidate to probable reseller. A general search for an Israeli Molecular Devices distributor/נציג/יבואן returned only VWR/Avantor catalogue pages; Molecular Devices'' own site does not name an Israeli partner in snippets, so the relationship is still not confirmed by the manufacturer. The 40-domain sweep surfaced a Molecular Devices FLIPR Penta product brochure hosted on Eisenberg Brothers'' own site (eisenbros.co.il/wp-content/uploads/2026/03/...), which indicates Eisenberg Bros. markets at least the FLIPR line in Israel. A follow-up search for ''Eisenberg Brothers'' + ''Molecular Devices'' found no explicit distributor statement (its older supplier lists name PerkinElmer, Thermo Fisher, Lonza, Affymetrix and Fluidigm), a second domain-restricted SpectraMax/FLIPR query returned only patents, and no other Israeli distributor site mentions SpectraMax. Marked ''unclear'' because the only evidence is the hosted brochure rather than a statement by Eisenberg Bros. or by Molecular Devices.', 'low', 'Indirect evidence only (brochure on the distributor''s site, March 2026); neither party states the relationship.', 'estimate', 'partial', 2026, 'confirmed_current', '+1 408-747-1700', '', '3860 N First Street, San Jose, CA 95134, USA', '', 'HQ; US/Canada toll-free +1 800-635-5577, Europe toll-free 00800 665 32860; UK office 1180 Eskdale Road, Wokingham RG41 5TU, +44 118 944 8000; general email obfuscated in results.');
INSERT INTO products (manufacturer_id, rank, name, description) VALUES (20, 1, 'SpectraMax iD5 / i3x', 'multi-mode microplate readers');
