INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (21, 'BD Biosciences & BD Diagnostic Solutions (part of Waters since Feb 2026)', 'BD Biosciences, BD Diagnostic Solutions, Becton Dickinson Life Sciences, FACS, FACSymphony, FACSDiscover, BACTEC, BD MAX, Phoenix, Kiestra; since Feb 2026: Waters Biosciences, Waters Advanced Diagnostics', 'Milford, Massachusetts (Waters Corp.); former BD Biosciences HQ San Jose, California; BD corporate HQ Franklin Lakes, New Jersey', 'USA', 'Waters Corporation (since 9 Feb 2026; previously Becton Dickinson)', 'Divisions of Waters Corporation (public, NYSE: WAT) after the Reverse Morris Trust with BD', 1897, 'https://www.bdbiosciences.com', 'Cell analysis (flow cytometry / cell sorting)', 8000, 2025, 'Rough share of the ~16,000 combined Waters/ex-BD headcount cited at the deal announcement; the ex-BD businesses alone were not disclosed. Figures recalled from company statements / filings and not re-verified online in this session.', 'USD 3.4 billion', 3400, 'CY2025E (basis used in the Jul-2025 deal announcement)', 'segment', 'Approx. USD 3.4 billion annual revenue for the combined BD Biosciences & Diagnostic Solutions business, as disclosed by Waters/BD at the 14 Jul 2025 announcement (recalled; not re-verified this session). Parent Waters Corporation stand-alone FY2025 revenue was roughly USD 3.1-3.2 billion (recalled). Post-combination Waters pro-forma revenue ~USD 6.5 billion (announcement figure, recalled).', 'reported', 'subsidiary', '[אימות עדכניות 10/2026] jobs.bd.com''s live Israel pages describe BD''s own commercial arm in Israel (direct entity since 2017, Life Science BDB/IDS and Medical units, ~400 associates) and the BD Caesarea manufacturing site, and a 2026 Israeli medical-device directory lists BD Israel at Harduf HaNehalim St 2, Caesarea with the BDBIsrael@bd.com address - the same address Waters gives for Augusta Life Sciences Israel Ltd. The Augusta entity was not re-surfaced by search but rests on Waters'' own 9-Feb-2026 transaction page. Note the BD careers text may predate the Feb-2026 separation; Lapidot''s BD listing was not re-seen in snippets. Searched BD Biosciences/BD Israel/Becton Dickinson Israel distributor/נציג/יבואן, Israeli distributor domains (BD, FACSymphony, FACSLyric, BD MAX, BACTEC), bd.com/waters.com, and the Waters-BD combination. bd.com''s Israel pages show BD''s own office and technical-service line in Caesarea, and Waters'' BD-transaction legal page (dated 9 Feb 2026) lists Augusta Life Sciences Israel Ltd., Caesarea, among the acquired SpinCo entities now wholly owned by Waters - i.e. the ex-BD Biosciences & Diagnostic Solutions business has its own Israeli entity under Waters. Waters states there are ''no changes for customers at this time'' and that BD remains legal manufacturer of certain regulated products until registrations transfer, so sales/service of FACS, BD MAX and BACTEC in Israel presumably continue from the Caesarea operation, but no page spelled out the post-combination commercial arrangement; no independent Israeli distributor for BD flow cytometers or BD diagnostics was found (Almog Diagnostic distributes competing Cytek/Miltenyi/Slingshot lines; Lapidot lists BD without product scope). Lapidot''s history page says it became BD''s local representative in 1992; whether this covers the former BD Biosciences / Diagnostic Solutions lines after the Feb-2026 Waters combination is not stated. A 2026 directory lists BD Israel (Harduf HaNehalim St. 2, Caesarea, BDBIsrael@bd.com) and names Elad Health (+972 3 769 3000) as a BD distributor; both unverified.', 'medium', 'Entities verified on bd.com and waters.com; the operating split between BD Israel and the Waters-owned Augusta entity after Feb 2026 is inferred, not documented.', 'estimate', 'verified', 2026, 'confirmed_current', '', 'BDBIsrael@bd.com', 'Harduf HaNehalim St. 2, Caesarea, Israel', '', 'Israel office (BD Israel, per third-party 2026 directory; no phone shown). Nothing found for Augusta Life Sciences Israel Ltd. (2 searches). Status conflicting: BD careers site describes a Caesarea infusion-pump site (ex-Caesarea Medical Electronics, acquired 2017), while Startup Nation Central marks BD as ceased operating in Israel Jan 2025 (Calcalist: manufacturing center closing, 200 layoffs). BD''s EU Cato page refers Israeli inquiries to distributor Elad Health, +972 3 769 3000.');
