erified', 2026, 'confirmed_current', '+1 608-274-4330', '', '2800 Woods Hollow Road, Madison, WI 53711, USA', 'https://ita.promega.com/en/support/contact-promega/', 'HQ (official contact page); toll-free +1 800-356-9526, fax +1 608-277-2516; no HQ email shown (UK orders: ukcustserve@promega.com).');
