INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (31, 'Hamilton Company', 'Hamilton Bonaduz AG, Hamilton Robotics, Hamilton Storage, Hamilton Process Analytics (Hamilton Medical AG is a separate sister company)', 'Reno, Nevada (co-headquarters: Franklin, Massachusetts and Bonaduz, Graubuenden, Switzerland)', 'USA', '', 'Private (family-owned, Hamilton family)', 1947, 'https://www.hamiltoncompany.com', 'Liquid handling & lab automation', 3000, NULL, 'Company self-description cited via the Canton Graubuenden business-location testimonial page: ''around 3000 people worldwide, more than 1200 of them in Bonaduz and Domat/Ems'' (page undated, likely 2022-2024). Revelio Labs profile-based estimates are lower (Hamilton Co. ~2,045, Sep-2025; Hamilton Bonaduz AG ~640, Dec-2025) but cover individual entities only. A 2020 Blick article cited 1,450 staff in Graubuenden alone.', 'USD ~600 million (trade estimate; private)', 600, '2024 (estimate)', 'estimate', 'Hamilton (Reno NV / Bonaduz CH) is family-owned and publishes no revenue; trade estimates range USD 500-800M for the robotics, storage and syringe businesses combined. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', '[אימות עדכניות 10/2026] Re-confirmed on the manufacturer''s side: Hamilton''s live ''Find a Distributor'' (laboratory products) page lists Danyel Biotech (Rehovot, danyel.co.il) and Ophir Analytical (Rosh Ha''ayin; lab syringes, needles, Microlab 600 diluter/dispenser, GC septa, HPLC columns) for Israel, and its process-analytics sensor distributor page lists Tarom Applied Technologies Ltd. (Petach-Tikva, tarom.co.il). Hamilton says it sells directly through its website and via major distributors; the exact Hamilton business lines covered by Danyel (robotics/storage) are still not itemised in the snippet. Danyel Biotech''s home page lists Hamilton among the brands it works with (seen in a search excerpt); which Hamilton business (robotics / storage / syringes) is not stated. Danyel Biotech''s site has Hamilton and Hamilton Storage brand pages.', 'medium', '', 'company', 'verified', 2026, 'confirmed_current', '+1 775 858 3000', '', '4970 Energy Way, Reno, NV 89502, USA', 'https://www.hamiltoncompany.com/contact', 'HQ (Reno). Toll-free +1 800 648 5950, fax +1 775 856 7259 per the official global-headquarters page. No general email seen (a 2014 exhibitor listing gave oem@hamiltoncompany.com - OEM-specific and old).');
