INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (33, 'Carl Zeiss AG – Research Microscopy Solutions', 'ZEISS; Carl Zeiss Microscopy GmbH; ZEISS Research Microscopy Solutions (RMS); Industrial Quality & Research segment', 'Oberkochen, Baden-Wuerttemberg (microscopy business unit in Jena)', 'Germany', 'Carl Zeiss AG (100% owned by the Carl Zeiss Foundation / Carl-Zeiss-Stiftung)', 'Private (foundation-owned; sub-group Carl Zeiss Meditec AG is listed, XETRA: AFX)', 1846, 'https://www.zeiss.com/microscopy', 'Light microscopy & imaging', 46622, 2025, 'ZEISS Group headcount, fiscal year 2024/25 (ended 30 Sep 2025): 46,622 (prior year 46,485); >7,300 in R&D. Research Microscopy Solutions headcount is not disclosed separately.', 'EUR 11.896 billion', 13086, 'FY2024/25 (ending Sep-2025)', 'parent', 'ZEISS Group revenue EUR 11.896 billion (+9%; EBIT EUR 1.552 billion, 13% margin). Segment split: Semiconductor Manufacturing Technology EUR 5.055 bn, Industrial Quality & Research EUR 2.334 bn (~USD 2,567 m; this segment contains Research Microscopy Solutions together with Industrial Quality Solutions - RMS alone is not disclosed), Medical Technology EUR 2.704 bn, Consumer Markets EUR 1.569 bn. (Carl Zeiss Meditec AG separately reported EUR 2,227.6 m revenue and 5,784 employees for FY2024/25.)', 'reported', 'distributor', '[אימות עדכניות 10/2026] Getter Group''s live site keeps Zeiss in its brand list (lab microscopes, hospital microscopes, cameras) and its English About page calls Getter the exclusive representative; LinkedIn posts by Getter Bio Med''s Scientific Light Microscopy team tagged Zeiss at IMEC 2025 (Jerusalem) and ISM 2026, so the research-microscopy relationship is active in 2025-2026. The ZEISS Israel site (zeiss.co.il, Carl Zeiss SMS Ltd.) is live but remains a semiconductor/ophthalmology entity and is not shown as a microscopy sales team. zeiss.com exposes no Israel entry for microscopy partners (its only Israeli listing is OpteamX, Azor, for industrial camera lenses, out of scope). Getter BioMed (גטר ביומד, Getter Group) states on its own site that it imports, markets and professionally supports ZEISS laboratory microscopes in Israel under the ''צייס ישראל'' banner, listing LSM 900 and LSM 980 Airyscan confocals, Axioscope 7, Axiovert 5 digital and ZEISS dental/surgical microscopes. zeiss.com was not checked (search budget) and some Getter pages are about three years old, so current exclusivity should be confirmed with ZEISS. Other ZEISS lines have separate Israeli importers (eyeglass lenses via Lapidot/LuxVision, camera lenses and binoculars via A.B.S.), which are not microscopy channels. Getter Group''s brand page lists Zeiss (described there as an optics company) among the brands it represents; scope for research microscopy unconfirmed.', 'high', 'Distributor''s own site with explicit ZEISS-Israel microscopy positioning and current LSM 900/980 listings; manufacturer page not checked.', 'parent', 'verified', 2026, 'confirmed_current', '', '', '', '', '');
INSERT INTO products (manufacturer_id, rank, name, description) VALUES (33, 1, 'ZEISS LSM 980 / LSM 990 with Airyscan 2', 'confocal laser scanning microscopes for live-cell imaging');
INSERT INTO products (manufacturer_id, rank, name, description) VALUES (33, 2, 'ZEISS Axio Observer / Axio Imager', 'inverted and upright research light microscope platforms');
