INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (34, 'Evident (ex-Olympus Scientific Solutions)', 'EVIDENT; formerly Olympus Scientific Solutions / Olympus Corporation scientific business (Olympus microscope brand heritage since 1919)', 'Tokyo (Shinjuku)', 'Japan', 'Bain Capital Private Equity (acquired from Olympus Corporation, closed April 2023, JPY 427.6 billion)', 'Private equity (Bain Capital)', 2022, 'https://www.evidentscientific.com', 'Light microscopy & imaging', 4300, 2023, '''More than 4,300 employees in 24 countries'' per Evident''s April-2023 announcement of the Bain Capital acquisition; no newer headcount seen.', 'approx. JPY 119 billion (last Olympus Scientific Solutions segment revenue, FY ending Mar-2022, pre-carve-out; recalled from Olympus reporting, unverified)', 797, 'FY ending Mar-2022 (pre-carve-out segment)', 'estimate', 'Evident has not published standalone revenue since the 2023 buyout; aggregator pages seen (Datanyze/ZoomInfo) give no reliable financials. The figure above is the magnitude of Olympus''s former Scientific Solutions segment and is recalled from memory - treat as an order-of-magnitude estimate only (~USD 0.8 bn/yr).', 'estimate', 'distributor', '[אימות עדכניות 10/2026] Eisenberg Bros.'' site is live with current Evident content (an ''EVIDENT OLYMPUS launches APEXVIEW APX100'' news page, Evident OEM microscope components and the MVX10 macro zoom page), which keeps it as the Israeli channel on the distributor side; evidentscientific.com still exposes no Israel distributor in snippets. Getter Group could not be re-confirmed for Olympus/Evident: the live Getter brand list seen in snippets (Agfa, Konica Minolta, Zeiss, KaVo, Canon, etc.) did not show Olympus, so it is kept as older evidence only. Searched ''Evident/Olympus microscope Israel distributor/נציג/יבואן'', ''Eisenberg Olympus/Evident'', Hebrew ''אייזנברג Olympus/Evident'', the brand across the Israeli distributor domains and evidentscientific.com. Eisenberg Bros. Ltd. (eisenbros.co.il) carries the Evident range on its own site (industrial microscopes BX53M/GX53/LEXT/DSX/MX63/SZX plus Evident OEM components), consistent with its 2009 listing as Olympus microscope supplier and with a LinkedIn post by an Eisenberg applications specialist promoting Evident FV5000/FV4000 confocal demos in Israel. Evident''s own locations page has no Israel office and its distributor network is not listed by country, so no manufacturer-side confirmation was seen; the 2009 Eisenberg hint is therefore still true as of the distributor''s current website. Evident is owned by Bain Capital since Jan 2023. Getter Group''s about page lists Olympus among the brands it exclusively represents in Israel (~2 years old); whether this covers Evident research microscopes or only Olympus medical products is not stated.', 'medium', 'Distributor''s own current product pages verify the relationship; no Evident-side distributor listing for Israel was found, and the exact status (exclusive/authorized) is not stated.', 'company', 'verified', 2026, 'confirmed_current', '+81 3 6901 4600', '', 'Shinjuku Monolith, 3-1 Nishi-Shinjuku 2-chome, Shinjuku-ku, Tokyo, Japan', '', 'HQ (Global Headquarters per company outline page). Phone is the Japan headquarters line on Evident''s locations pages (https://evidentscientific.com/fr/locations), which list the Japan HQ/R&D center at 67-4 Takakura-machi, Hachioji-shi, Tokyo 192-0033. Only privacy-request emails seen (e.g. Global-privacy@evidentscientific.com); no general email.');
