INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, evidence_year, status, source) VALUES (70, 36, 'Bargal Analytical Instruments Ltd.', 'ברגל ציוד אנליטי', 'distributor', 'JEOL electron microscopes - sales and service; Bargal''s live catalogue names JEOL as manufacturer for JSM-IT210, JSM-IT200, JSM-IT510, JSM-IT710HR, benchtop JCM-7000 NeoScope, JEM-1400Flash, JEM-F200, CRYO ARM 300 (JEM-Z300FSC) and CRYO ARM 300 II (JEM-3300); jeol.com lists Bargal (Shaked St 10, Shoham, +972-3-9796-533) as the Israel contact. NMR/MS lines not confirmed.', 'https://bargal.co.il', '+972-3-979-6533', 'sales@bargal.co.il', '10 Shaked Street, Modi''in Industrial Park, Shoham 6085102', '', 2026, 'current', 'https://bargal.co.il/product/scanning-electron-microscope-sem-jsm-it210/');
INSERT INTO sources (manufacturer_id, url) VALUES (36, 'https://www.jeol.com/service_support/');
