INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (37, 'Hitachi High-Tech', 'Hitachi High-Technologies (name until 2020); Hitachi High-Tech Science; Hitachi High-Tech Analytical Science; Nissei Sangyo (original name)', 'Tokyo (Minato, Toranomon)', 'Japan', 'Hitachi, Ltd. (wholly owned since the 2020 tender offer and delisting)', 'Subsidiary of Hitachi, Ltd. (public, TSE: 6501)', 1947, 'https://www.hitachi-hightech.com', 'Electron microscopy & X-ray / materials characterization', 12400, 2025, 'Consolidated headcount ~12,000-12,500 (recalled, unverified).', 'JPY ~750 billion (estimate)', 5000, 'FY ending Mar-2025 (estimate)', 'estimate', 'Hitachi High-Tech has been wholly owned by Hitachi, Ltd. since 2020 and no longer publishes stand-alone results; order of magnitude from its last public filings and Hitachi segment data. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'unclear', '[אימות עדכניות 10/2026] Hitachi High-Tech''s live global-network page still lists Hitachi High-Tech Israel, Ltd. (Kiryat Gat office, P.O. Box 1000, MS: Hitachi LC2-3S, Kiryat Gat 82109, +972-8-666-6342, fax +972-8-666-6939), renamed from H.H.T.A. Semiconductor Equipment Israel in April 2020, so the subsidiary is current but remains a semiconductor-equipment service entity. No Israeli distributor for Hitachi SEM/TEM or analytical instruments surfaced across 21 Israeli distributor domains or in a 2025-2026 news query; Hitachi tabletop/FE-SEMs appear only on Quantum Design Europe''s German, Austrian and Italian sites, and Quantum Design''s Israel site (qd-europe.com/il) is run from its ''Italy and Israel branch office'' in Rome without any explicit statement that Hitachi SEM is offered to Israel. The lab-instrument channel therefore remains unclear. Hitachi High-Tech''s global-network page lists Hitachi High-Tech Israel, Ltd. (Kiryat Gat office, P.O. Box 1000, MS: Hitachi LC2-3S, Kiryat Gat 82109), renamed in 2020 from H.H.T.A. Semiconductor Equipment Israel Ltd.; the Dunsguide entry (היטאצ''י היי-טק ישראל) classifies it under semiconductors/electronic components in Tel Aviv. This subsidiary supports semiconductor process equipment and no source shows it selling SEM/TEM or analytical (XRF, spectrophotometer) products; Hitachi High-Tech Analytical Science''s contact page says inquiries are routed to a regional distributor, and the Israeli distributor was not identified (Bargal, which sells SEM/TEM in Israel, represents JEOL). The lab-instrument channel therefore stays unclear although the Israeli entity is verified.', 'low', 'Subsidiary verified on hitachi-hightech.com but it is semiconductor-focused; SEM/TEM/analytical distributor not found.', 'estimate', 'verified', 2026, 'confirmed_current', '+81 3 3504 7111', '', 'Toranomon Hills Business Tower, 1-17-1 Toranomon, Minato-ku, Tokyo 105-6409, Japan', '', 'HQ - Israel office not found: two searches (Israel office; ''Hitachi High-Tech Israel'' Ltd) returned no Israeli listing, so the Tokyo head office is recorded instead (per company outline and GlobalData). EMEA support: Hitachi High-Tech Europe GmbH, Europark Fichtenhain A12, 47807 Krefeld, Germany (https://www.hitachi-hightech.com/eu/en/support/technical-support/). US: 10 North Martingale Road, Suite 500, Schaumburg, IL 60173, +1 847 273 4141.');
