INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (41, 'Malvern Panalytical (Spectris)', 'Malvern Instruments, PANalytical (Philips Analytical heritage); Spectris Scientific division', 'Malvern, Worcestershire (second HQ: Almelo, Netherlands)', 'UK', 'Spectris (owned by KKR since December 2025)', 'Subsidiary of Spectris — Private equity (KKR; GBP 4.7bn take-private completed December 2025, Spectris delisted 5 Dec 2025)', 2017, 'https://www.malvernpanalytical.com', 'Electron microscopy & X-ray / materials characterization', 7600, 2025, 'Spectris group headcount (~7,600, per 2025 take-private coverage). Malvern Panalytical''s own headcount was not obtained from a source in this session (it is generally described as roughly 2,000+ staff).', 'GBP 776.7 million', 1010, 'FY2024', 'segment', 'Spectris Scientific segment (Malvern Panalytical + Servomex etc.) FY2024; Spectris was taken private by KKR in Dec 2025 and no longer reports.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Dr. Uri Golik''s live site keeps a Malvern Panalytical manufacturer page, a Malvern Panalytical video page and current product pages (Mastersizer 3000/3000+, Morphologi 4 and 4-ID, Zetasizer Pro, NanoSight NS300), confirming the relationship on the distributor side in 2026. Malvern Panalytical''s own ''Find your local contact'' directory includes an Israel entry whose name was not exposed in the snippet, and the only manufacturer-side naming of Golik remains the 2013 Isranalytica article. Searched generic queries, 27 Israeli distributor domains and malvernpanalytical.com. Dr. Uri Golik Chemical Instrumentation has a current ''Malvern Panalytical'' manufacturer page and product pages for Zetasizer Pro, Mastersizer 3000+, NanoSight NS300, Morphologi 4, Archimedes and MicroCal PEAQ-DSC; Malvern''s own 2013 Isranalytica article calls Dr Golik its distributor (best-supplier award, CEO Dorit Bilman Golik) and a 2011 Malvern contact sheet attached to an Israeli government tender lists Golik, Tel Aviv, as Israel sales/service. Caveat: the manufacturer-side confirmations pre-date the 2017 Malvern/PANalytical merger, and XRD (ex-PANalytical) products were not seen on Golik''s pages.', 'high', 'Current distributor brand page corroborated by the manufacturer''s own (older) article and contact sheet.', 'parent', 'verified', 2026, 'confirmed_current', '+44 1684 581201', '', 'Enigma Business Park, Grovewood Road, Malvern, WR14 1XZ, UK', 'https://www.malvernpanalytical.com/en/about-us/contact-us/Contact-sales', 'HQ (UK head office, Malvern Panalytical Ltd). Phone is the sales line per the official contact page; support +44 1684 581249. Netherlands head office: Malvern Panalytical B.V., Lelyweg 1, 7602 EA Almelo, sales +31 546 534 444. US: 117 Flanders Road, Westborough, MA 01581, +1 508 768 6400 (directory). No general email seen (an older IUCr directory lists info@panalytical.com, likely outdated).');
