INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (43, 'Anton Paar', 'Anton Paar Group AG; Quantachrome Instruments (acquired 2018, now Anton Paar QuantaTec); Brabender (acquired 2023)', 'Graz', 'Austria', 'Anton Paar Group AG (owned by the charitable Santner Foundation)', 'Private (foundation-owned — Santner Foundation)', 1922, 'https://www.anton-paar.com', 'Diversified analytical & life-science instruments', 4500, 2025, '''4,500+ employees'' per the company factsheet (dated June 2026) and Wikipedia; Revelio Labs shows 2,816 (Sept 2025) for a narrower legal-entity scope.', 'EUR 629 million', 692, 'FY2025', 'company', 'Net sales revenue 2025 EUR 629m per Anton Paar factsheet (June 2026); 14.5% of turnover invested in R&D.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Prime Lab''s live home page still lists Anton Paar rheometers, density meters and SAXS systems among its products (the page is about 2.6 years old per the search index), keeping it as the distributor-side evidence. anton-paar.com exposes no Israel subsidiary or distributor in snippets (35 subsidiaries, 30+ distribution partners, contact via web form), so exclusivity and full product scope remain stated by the distributor only. Prime Lab Scientific Instruments Ltd. (Kfar Saba) lists Anton Paar GmbH among its partner manufacturers on its own site, hosts an Anton Paar SAXS product page, and describes itself as the local partner/distributor offering import, installation, IQ/OQ/PQ, calibration and after-sales service. The BioFindly directory independently names Prime Lab as the single Israeli representative handling sales, service and quotes for Anton Paar. Not cross-checked on anton-paar.com (search budget), so exclusivity and the full product scope are stated by the distributor and a directory rather than by the manufacturer.', 'medium', 'Distributor''s own site plus an Israeli directory; manufacturer''s distributor page not seen.', 'company', 'verified', 2026, 'confirmed_current', '+43 316 257-0', '', 'Anton-Paar-Straße 20, 8054 Graz, Austria', '', 'HQ (Anton Paar GmbH). Phone/address per fluidhandlingpro directory (fax +43 316 257 257); no general HQ email seen. Official page for Anton Paar Austria GmbH (sales & service Austria), Ankerstraße 6, 8054 Graz: +43 316 269 571, info.at@anton-paar.com (https://www.anton-paar.com/au-en/about-us/anton-paar-companies/anton-paar-austria-gmbh).');
