INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (46, 'JASCO Corporation', 'Japan Spectroscopic Co.; JASCO International, JASCO Inc. (Easton, MD, USA), JASCO Europe, JASCO Deutschland', 'Hachioji, Tokyo', 'Japan', '', 'Private', 1958, 'https://www.jasco-global.com', 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 400, 2024, 'Roughly 400 employees in Japan plus overseas subsidiaries (recalled, unverified).', 'JPY ~12 billion (trade estimate; private)', 80, 'FY2024 (estimate)', 'estimate', 'JASCO (Hachioji, Tokyo) is privately held; order-of-magnitude estimate. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', '[אימות עדכניות 10/2026] Re-confirmed on both sides: JASCO''s live ''Where to buy'' (jasco.de, Distributors Middle East) and worldwide-locations pages (jasco-global.com, jascoinc.com) list Ophir Analytical, Rosh-Ha''ayin, for Israel, and Ophir Analytical''s own live site (6 Hamelacha St, Park-Afek, Rosh-Ha''ayin 48091, +972-3-9022277; distributor since 1991 of chromatography and spectroscopy instruments) matches, though it does not name JASCO in the pages seen. Website corrected to the https domain. JASCO''s own ''Where to buy'' and ''Worldwide Locations'' pages (jascoeurope.com, jasco.de, jasco-global.com, jascoinc.com) list Ophir Analytical Ltd., Rosh Ha''ayin, as the distributor for Israel; JASCO Europe is responsible for sales, service and support across Europe, the Middle East and Africa. The listing is at most about nine months old per the search index. Ophir Analytical''s own site was not opened, and the earlier distributor-domain and Hebrew searches missed it because it is not in the known-distributor list.', 'high', 'Named on the manufacturer''s own where-to-buy / locations pages.', 'estimate', 'verified', 2026, 'confirmed_current', '', '', '2967-5 Ishikawa-machi, Hachioji-shi, Tokyo, Japan', '', 'HQ. Address per Metoree directory only (business directories list JASCO International Co., Ltd. at 4-21 Sennin-cho 2-chome, Hachioji 193-0835); no HQ phone/email seen in two searches. US office (JASCO Inc.): 28600 Mary''s Court, Easton, MD 21601, +1 800 333 5272, sales@jascoinc.com (https://chromatographyonline.com/view/jasco).');
