INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (47, 'SPECTRO Analytical Instruments (AMETEK)', 'SPECTRO (AMETEK Materials Analysis Division); SPECTRO ARCOS, SPECTROBLUE, SPECTROGREEN, SPECTRO XEPOS, SPECTROMAXx, SPECTRO MS', 'Kleve', 'Germany', 'AMETEK, Inc.', 'Subsidiary of AMETEK (public, NYSE: AME) — acquired 2005', 1979, 'https://www.spectro.com', 'Elemental & materials analysis', 500, 2024, 'SPECTRO (Kleve) employs roughly 400-500; parent AMETEK ~21,500 (recalled, unverified).', 'USD 6.94 billion', 6940, 'FY2024', 'parent', 'AMETEK group revenue (parent); SPECTRO alone is not disclosed (order of EUR 100-150M, trade estimate).', 'mixed', 'distributor', '[אימות עדכניות 10/2026] Changed from unclear to distributor: Spectro (Israel) Ltd.''s live site states it is the exclusive representative in Israel for SPECTRO Analytical Instruments, lists ICP ARCOS, ICP SPECTROGREEN and ICP GENESIS under ICP-OES plus SPECTROPORT mobile OES and SPECTRO xSORT handheld XRF, and claims about 50% of the Israeli ICP-OES market. spectro.com''s ''SPECTRO Worldwide'' locator still exposes no Israel entry in snippets (Middle East handled from Dubai), so the relationship is confirmed on the distributor side only. Spectro (Israel) Ltd. is an independent Israeli company (est. 1994) that is also Elementar''s listed distributor. No source seen names an Israeli distributor or office for SPECTRO Analytical Instruments: spectro.com''s ''SPECTRO Worldwide'' locator and AMETEK''s global-locations page surfaced only a Middle East office in Dubai, and the distributor-domain, Hebrew and tender-angle queries returned nothing. One lead needs verification: Spectro (Israel) Ltd., Rishon LeZion (spectro.co.il, est. 1994), an independent analytical-instrument distributor that claims about 50% of the Israeli ICP-OES market and is Elementar''s listed Israeli distributor; its name and ICP-OES focus suggest a possible link to SPECTRO, but the pages seen (its own site and LinkedIn) confirm only SYKAM, so it is NOT recorded here as a SPECTRO representative. A newroad.co.il ''XRF & GDS elemental analysers in Israel'' page also surfaced without naming SPECTRO.', 'low', 'No confirming source; the Spectro (Israel) Ltd. lead is unverified and may be a coincidence of names.', 'estimate', 'verified', 2026, 'changed', '+49 2821 892-0', 'spectro.info@ametek.com', 'Boschstraße 10, 47533 Kleve, Germany', '', 'HQ. Address/phone per several directory listings (recyclinginside, yumda, fponthenet, jobvoting; fax +49 2821 892-2200); email from one older (2016-dated) listing - verify. US: 91 McKee Drive, Mahwah, NJ 07430, +1 201 642 3000 / +1 800 548 5809.');
