INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (48, 'Analytik Jena (Endress+Hauser)', 'Analytik Jena AG (former listed name); Biometra, CyBio; part of the Endress+Hauser Group', 'Jena', 'Germany', 'Endress+Hauser Group', 'Subsidiary of Endress+Hauser Group (private, family-owned, Switzerland)', 1990, 'https://www.analytik-jena.com', 'Analytical instruments (chromatography / mass spectrometry / spectroscopy)', 1000, 2024, 'Roughly 1,000 employees (recalled, unverified).', 'EUR ~180 million (trade estimate)', 200, '2024 (estimate)', 'estimate', 'Part of the privately held Endress+Hauser Group (~EUR 3.9B group revenue); Analytik Jena alone is not disclosed. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', '[אימות עדכניות 10/2026] All three distributor pages are live: Lifegene''s Biometra TAdvanced, TOne and TRobot II pages describe them as premium PCR instruments from Analytik Jena; Tamar Laboratory Supplies'' qTOWER³ page and its ''PCR instruments from Biometra'' project page are current; Lumitron''s About page describes UVP as a part of Analytik Jena. analytik-jena.com''s partners page lists global distribution and service partners by location but the Israel entry was not exposed in snippets, so the chemical-analysis portfolio (AAS, ICP, TOC) still has no confirmed Israeli channel. Three Israeli distributors carry Analytik Jena life-science lines on their own sites: Lifegene (Biometra TOne and TAdvanced thermal cyclers), Tamar Laboratory Supplies (qTOWER³ real-time PCR) and Lumitron (UVP bio-imaging, described as ''a part of Analytik Jena''). The BioFindly directory also lists one Israeli representative for Analytik Jena tied to qPCR/spectrophotometers (text garbled in the snippet). The chemical-analysis portfolio (AAS, ICP-OES/MS, TOC, mercury) has no confirmed Israeli channel: analytik-jena.com''s partner finder did not expose an Israel entry in search snippets.', 'medium', 'Life-science lines verified on distributor sites; analytical-chemistry channel unknown; manufacturer partner page not visible.', 'estimate', 'verified', 2026, 'confirmed_current', '+49 3641 77-70', 'info@analytik-jena.com', 'Konrad-Zuse-Str. 1, 07745 Jena, Germany', 'https://analytik-jena.com/contact', 'HQ. Fax +49 3641 77-9279; sales +49 3641 77 7444 / sales@analytik-jena.com; service +49 3641 77 7407 / service@analytik-jena.com; press presse@analytik-jena.com (official contact pages).');
