INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (49, 'Elementar Analysensysteme', 'Elementar; Isoprime (IRMS, acquired 2016); elemental-analysis heritage of Heraeus', 'Langenselbold (near Frankfurt)', 'Germany', '', 'Private (family/management-owned; spun out of Heraeus in 1990)', 1990, 'https://www.elementar.com', 'Elemental & materials analysis', 400, 2024, 'Roughly 400 employees (recalled, unverified).', 'EUR ~70 million (trade estimate; private)', 77, '2024 (estimate)', 'estimate', 'Family-owned (Langenselbold); order-of-magnitude estimate. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', '[אימות עדכניות 10/2026] Re-confirmed on the manufacturer''s side: Elementar''s live ''Contact worldwide'' page lists Spectro Israel Ltd., 10 Sacharov Street, Rishon LeZion, with phone and email as its Israeli contact (the snippet''s layout places it with organic elemental, nitrogen/protein and TOC analysers). Spectro Israel''s own live site confirms the Rishon LeZion address, its 1994 founding and its ICP-OES focus; it has no relation to SPECTRO Analytical/AMETEK beyond also representing that brand. Elementar''s own ''Contact worldwide / contact local'' pages list Spectro Israel Ltd., 10 Sacharov St., Rishon LeZion (+972 3 9693014, spectro@spectro.co.il, spectro.co.il) as its Israeli distributor. Spectro (Israel) Ltd. is an independent Israeli analytical-instrument distributor founded in 1994 (ICP-OES focus, also SYKAM HPLC/IC/amino-acid analysers), with no shown relation to SPECTRO Analytical/AMETEK. The product scope in Israel (CHNS/O, TOC, nitrogen/protein, IRMS) is implied by the manufacturer listing rather than itemised.', 'high', 'Named on the manufacturer''s own worldwide-contacts page; distributor''s site confirms the company exists at that address.', 'estimate', 'verified', 2026, 'confirmed_current', '+49 6184 9393-0', 'info@elementar.com', 'Elementar-Straße 1, 63505 Langenselbold, Germany', '', 'HQ. Fax +49 6184 9393-400; per the official legal notice. The UK portal imprint lists info@elementar.co.uk.');
