INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, evidence_year, status, source) VALUES (91, 52, 'Modotec Ltd.', 'מודוטק בע"מ', 'distributor', 'Hach water/wastewater analysis range per Modotec''s live site (supplier page describes Hach as the world leader in water and wastewater measurement, online and laboratory): online analyzers (BioTector B7000i TOC, Amtax sc ammonium, phosphorus/COD/silica/hardness), SC200/SC1000/SC1500 controllers (Claros), online/lab/portable turbidity and suspended-solids meters, UV and dissolved-oxygen meters, lab spectrophotometers/colorimeters, thermal reactors, incubators, titrators and test kits, portable/fixed samplers; scope therefore wider than the Hach Flow line recorded earlier. Caveat: Modotec''s product pages are roughly 4-7 years old and Hach''s own global-distributor locator did not show Israel in search snippets', 'https://www.modotec.co.il', '+972-4-991-9988', '', '16 Moshe Bernstein St., South Industrial Park, Acre (Akko) 2422238', '', 2026, 'current', 'https://www.modotec.co.il/%D7%A1%D7%A4%D7%A7%D7%99%D7%9D/');
