INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, evidence_year, status, source) VALUES (95, 53, 'Mercury (mercury-ltd.co.il; part of Gadot Chemicals Group)', 'מרקורי', 'distributor', 'Hanna Instruments'' official distributor for Israel per Hanna''s own live Israel page (pages.hannainst.com/israel): partnership listed as active since 2023; Mercury joined Gadot Chemicals Group in 2022 and offers Israeli research and industry a broad basket of products meeting regulatory requirements; sales and product contacts are on the mercury-ltd.co.il domain', 'https://www.mercury-ltd.co.il', '+972 3-938-7164', '', '12 Ha''avoda St., P.O. Box 159, Rosh Ha''ayin', 'https://eng.mercury-ltd.co.il/about_us', 2026, 'new', 'https://pages.hannainst.com/israel');
