INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (54, 'VELP Scientifica', 'VELP', 'Usmate Velate (Monza e Brianza)', 'Italy', '', 'Private', 1983, 'https://www.velp.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 200, 2024, 'Roughly 200 employees (recalled, unverified).', 'EUR ~40 million (trade estimate; private)', 44, '2024 (estimate)', 'estimate', 'VELP (Usmate Velate, Italy) is family-owned; order-of-magnitude estimate. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', '[אימות עדכניות 10/2026] Labotal''s live ''Represented Firms'' page lists VELP among the brands it represents, confirming the 2024 exclusivity statement on its VELP supplier page is still current. On the manufacturer side, VELP''s own distribution-awards page lists Israel among the countries where it has distributors but does not name the partner in the snippet. No other Israeli VELP channel (for general lab equipment such as stirrers) surfaced. Labotal (לבוטל) states on its own VELP supplier page that during 2024 it became the exclusive representative for VELP''s analytical product line in Israel (UDK Kjeldahl distillers, DKL digesters, NDA 702 Dumas nitrogen/protein analyser, fibre/fat extractors), and the BioFindly directory lists Labotal under VELP. The statement covers the analytical line only; VELP''s general lab equipment (stirrers, shakers, hotplates) may have a different Israeli channel, which was not found. velp.com was not checked (search budget).', 'high', 'Explicit, dated statement on the distributor''s own site plus directory corroboration; manufacturer page not checked.', 'estimate', 'verified', 2026, 'confirmed_current', '+39 039 628811', '', 'Via Stazione 16, 20865 Usmate (MB), Italy', 'https://velp.com/en-ww/where-we-are.aspx', 'HQ (VELP Scientifica Srl); no general email in results; US office VELP Scientific Inc., 40 Burt Drive Unit #1, Deer Park NY 11729, +1 631 573 6002');
