INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, evidence_year, status, source) VALUES (98, 55, 'Gamidor Diagnostics', 'גאמידור דיאגנוסטיקה בע"מ', 'distributor', 'Roche Tissue Diagnostics only: Gamidor''s live Tissue Diagnostics page offers IHC, molecular ISH and histochemical staining on automated slide-preparation instruments from VENTANA (Roche); not cobas/LightCycler', 'https://gamidor.co.il', '+972-3-927-7277', 'info@gamidor.co.il', 'Shaham 32, Petach Tikva', '', 2026, 'current', 'https://gamidor.co.il/en/tissue-diagnostics-2/');
