INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (56, 'Abbott Diagnostics', 'Abbott Core Laboratory Diagnostics; Abbott Rapid Diagnostics; Alinity; ARCHITECT; i-STAT; ID NOW; BinaxNOW; Panbio; Cell-Dyn', 'Abbott Park, Illinois', 'USA', 'Abbott Laboratories', 'Division of Abbott Laboratories (public, NYSE: ABT)', 1972, 'https://www.corelaboratory.abbott', 'Clinical / IVD laboratory analyzers', 114000, 2024, 'Abbott Laboratories total headcount (~114,000, Abbott 10-K for FY2024) — from memory, not verified this session; Diagnostics division headcount not disclosed. Founded: Abbott 1888; Diagnostics Division established 1972.', 'USD 9.3 billion (Diagnostic Products segment, approx.)', 9300, 'FY2024', 'segment', 'Abbott Diagnostic Products segment sales FY2024 ≈ USD 9.3 bn (Abbott total ≈ USD 42.0 bn); FY2025 Diagnostics ≈ USD 9 bn (lower COVID testing; approx., reported Jan 2026). From memory of Abbott 10-K / earnings releases; could not be verified this session (search budget exhausted, fetch failures) — verify.', 'reported', 'parent_subsidiary', '[אימות עדכניות 10/2026] Abbott''s live global-locations page and the Hebrew il.abbott site (contact page listing diagnostics among its product areas) confirm Abbott Medical Laboratories Ltd., Tel Aviv, as the current Israeli affiliate. Ilex Medical''s own investor material (2024 periodic report, April 2025) names Abbott among the companies it represents, so Ilex is kept as a current channel with 2025 evidence, product-line scope unconfirmed. A Hebrew tender search for Alinity in 2025-2026 found no tender naming the supplier. Searched ''"Abbott" Israel Alinity/Architect distributor/יבואן'', Hebrew ''אבוט מעבדות רפואיות'', the 29 Israeli distributor domains, mr.gov.il and Abbott''s own domains. Abbott''s global-locations page lists Abbott Medical Laboratories Ltd. in Tel Aviv under ''Nutrition, Pharmaceuticals and Diagnostics'', and the Hebrew ''Abbott in Israel'' page (il.abbott) says the affiliate has ~160 employees and that its diagnostics work in Israel covers molecular and laboratory tests; Globes reported the representative office opened in 2004 and Abbott''s later expansion in Israel. No Israeli distributor for Alinity/Architect appeared on any distributor site. Caveat: no source states explicitly that the analyzers are sold and serviced by the affiliate itself, and the only tender hits concern Abbott Informatics (STARLIMS), not analyzers. Ilex Medical''s profiles (SID Israel directory, Globes) list Abbott among the diagnostics companies it represents, alongside Abbott''s own Israeli affiliate.', 'high', 'Israel finding only: entity named on Abbott''s own pages; direct channel for Alinity/Architect inferred from the affiliate''s diagnostics scope and absence of a distributor.', 'company', 'verified', 2026, 'confirmed_current', '+972 3 769 1000', '', 'Abbott Medical Laboratories Ltd., Atidim Science Park, Bldg. 4, P.O. Box 58099, Tel Aviv 61580, Israel', 'https://www.abbott.com/global-locations-contacts/israel.html', 'Israel office; official Abbott global-locations page; fax +972 3 649 4973');
