INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, evidence_year, status, source) VALUES (102, 57, 'Siemens Healthineers Israel (legal entity name believed to be Siemens Healthcare Ltd., Israel — not verified)', '', 'subsidiary', 'All Siemens Healthineers businesses in Israel including laboratory diagnostics: the live Israeli contact page gives ''Siemens Healthineers Israel, Siemens HealthCare Ltd., Industrial Park Afeq, Hamelacha Street 14, 48091 Rosh Ha''ayin'' (legal entity name now verified; address updated from Hod Hasharon/unknown); Siemens'' regional legal-information page lists the same address for Siemens Ltd / Siemens Mobility / Siemens Healthineers; the Israeli site features blood-gas testing, and the 2019 Atellica customer event page (Head of Diagnostics, Siemens Healthineers Israel) remains the diagnostics-specific local document', 'https://www.siemens-healthineers.com/il', '+972-73-3219803', '', '14 Hamelacha St., Park Afeq, Rosh Ha''ayin', 'https://www.siemens.com/en-gb/content/hotline-israel/', 2026, 'current', 'https://www.siemens-healthineers.com/il/how-can-we-help-you');
INSERT INTO sources (manufacturer_id, url) VALUES (57, 'https://www.siemens-healthineers.com/il/news-and-events/conferences-events-new/israel-local-events/atellica-solution-event-2019');
