INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (58, 'bioMérieux', 'BioFire Diagnostics; VITEK; BACT/ALERT; VIDAS; BIOFIRE FILMARRAY; SPOTFIRE; Specific Diagnostics', 'Marcy-l''Étoile (Lyon)', 'France', 'Institut Mérieux (controlling shareholder)', 'Public (Euronext Paris: BIM); majority-controlled by Institut Mérieux (Mérieux family)', 1963, 'https://www.biomerieux.com', 'Clinical / IVD laboratory analyzers', 14000, 2024, 'Approx. 14,000 employees in ~45 countries (bioMérieux 2024 reporting) — from memory, not verified this session.', 'EUR 3.98 billion (approx.)', 4378, 'FY2024', 'company', 'FY2024 sales ≈ EUR 3.98 bn (double-digit organic growth driven by BIOFIRE); FY2025 ≈ EUR 4.1-4.2 bn (approx., reported early 2026). From memory of bioMérieux results releases; not verified this session — verify.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Ilex Medical''s live site re-confirms it as bioMérieux''s Israeli channel: the BIOFIRE catalogue page (FilmArray panels) is still online, the blood-cultures page adds bioMérieux''s BACT/ALERT VIRTUO automated blood-culture system and extraction instruments, and Ilex''s 2024 periodic report (published April 2025) lists bioMérieux as its microbiology line, so the scope now covers BIOFIRE and BACT/ALERT; VITEK is still not named explicitly. bioMérieux''s live press release confirms the 2025 Accellix acquisition (Jerusalem site). bioMérieux''s worldwide page shows no Israeli subsidiary (the regional subsidiary is in the Middle East/Dubai). An extended Hebrew/English query surfaced Ilex Medical''s own catalogue page ''BIOFIRE - Ilex Medical'', which states that Ilex offers bioMérieux''s BioFire nested multiplex PCR panels (respiratory, CSF, gastro, positive blood culture, joint infection) to Israeli customers; the page is roughly 2.5 years old, so current status should be confirmed. No source names the Israeli channel for VITEK or BACT/ALERT: the 40-domain sweep, a Hebrew tender query (''מכרז VITEK 2 ביומרייה'') and an ''Israel'' query restricted to biomerieux.com returned only clinical papers, foreign contract news and unrelated pages. bioMérieux''s only Israeli entity remains Accellix (Jerusalem R&D/manufacturing, acquired 2025); upgraded from ''unclear'' to ''distributor'' on the strength of the Ilex page. Ilex Medical''s company profile (SID Israel directory) lists bioMérieux with Abbott, Hologic, Grifols, IL and Sebia among the companies it represents; not re-confirmed on biomerieux.com.', 'medium', 'Distributor''s own site confirms the BIOFIRE line; the VITEK/BACT/ALERT distributor is still unidentified and the Ilex page dates from ~2024.', 'company', 'verified', 2026, 'confirmed_current', '', '', 'Shlomo Momo Ha''levi 5, Jerusalem, Israel (Accellix; third-party startup directory, unverified)', '', 'Israel office; 2 searches found no Israeli phone/email; Accellix (acquired Jan 2026, ~70 staff across San Jose CA and Jerusalem) street address only from https://slimpages.startupim.com/min_company_page/leukodx; bioMérieux Middle East hub is in Dubai; group HQ 100 Allée Louis Pasteur, 69280 Marcy-l''Étoile, France (third-party profile)');
INSERT INTO products (manufacturer_id, rank, name, description) VALUES (58, 1, 'VITEK 2 / VITEK MS PRIME', 'automated microbial ID/AST and MALDI-TOF identification');
INSERT INTO products (manufacturer_id, rank, name, description) VALUES (58, 2, 'BACT/ALERT VIRTUO', 'automated blood-culture system');
INSERT INTO products (manufacturer_id, rank, name, description) VALUES (58, 3, 'BIOFIRE FILMARRAY TORCH / SPOTFIRE', 'syndromic multiplex PCR panels');
INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, evidence_year, status, source) VALUES (103, 58, 'Accellix (bioMérieux company), Jerusalem', '', 'subsidiary', 'R&D/manufacturing site of Accellix (automated flow-cytometry QC for pharma; staff in San Jose and Jerusalem), acquired by bioMérieux in 2025 per bioMérieux''s live press release - not a sales office for VITEK/BACT/ALERT/BIOFIRE', 'https://www.accellix.com/', '', '', 'Shlomo Momo ha-Levi St 5, Jerusalem', '', 2025, 'current', 'https://www.biomerieux.com/us/en/journalists/press-releases/acquisition-accellix-pharma-quality-control.html');
INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, evidence_year, status, source) VALUES (104, 58, 'Ilex Medical Ltd.', 'אילקס מדיקל בע"מ', 'distributor', 'bioMérieux microbiology line in Israel: Ilex''s live BIOFIRE catalogue page offers BioFire FilmArray nested multiplex PCR panels (respiratory, CSF, GI, positive blood culture, joint infection); Ilex''s live blood-cultures page lists bioMérieux blood-culture systems incl. the VIRTUO automated system (BACT/ALERT VIRTUO) and nucleic-acid extraction instruments; Ilex''s 2024 periodic report (April 2025) lists bioMérieux as its microbiology line. VITEK not seen explicitly', 'https://www.ilexmedical.com', '+972-3-9385500', '', '7 HaTnufa St., Petah Tikva', '', 2026, 'current', 'https://www.ilexmedical.com/catalog_products/biofire/');
