INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (59, 'Sysmex', 'Sysmex; formerly TOA Medical Electronics (renamed 1998); XN-Series, XR-Series, UN-Series, CN-Series', 'Kobe (Hyogo)', 'Japan', '', 'Public (TSE Prime: 6869)', 1968, 'https://www.sysmex.co.jp/en/', 'Clinical / IVD laboratory analyzers', 11000, 2025, 'Consolidated headcount ≈ 11,000 as of March 2025 (approx.; from memory of Sysmex''s integrated report, not verified this session).', 'JPY 511.4 billion', 3426, 'FY ending Mar-2025', 'company', 'Net sales for the fiscal year ended 31 March 2025 ≈ JPY 511 bn (from memory of Sysmex''s results; not verified this session). Results for FY ending Mar-2026 (published May 2026) were not verified.', 'reported', 'distributor', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Sysmex Europe''s live distributor directory still lists Dover Medical & Scientific Equipment (Herzliya) for Israel, which counts as current manufacturer-side evidence; the listing appears under a Sysmex UK Ltd. heading, so Dover may be served through Sysmex UK. A search restricted to dovermed.co.il surfaced only robotic-surgery content and no Sysmex product page, so the distributor-side confirmation and the product scope remain open. No 2024-2026 Israeli tender naming the Sysmex supplier was found within the budget. Searched ''"Sysmex" Israel distributor/נציג/יבואן'', Hebrew ''סיסמקס'', the 29 Israeli distributor domains, mr.gov.il/gov.il and sysmex-europe.com. Sysmex Europe SE''s distributor directory lists ''DOVER MEDICAL & SCIENTIFIC EQUIPMENT'' under Israel (Sysmex EMEA works through affiliates and local partners, with Sysmex Middle East FZ-LLC in Dubai as the regional hub). GlobalData names Sysmex the leading hematology-analyzer vendor in Israel (2023), and an ISRAC accreditation document lists Siemens/Sysmex CS coagulation analyzers, which Siemens Healthineers distributes under its own brand. Caveats: the Dover entry was seen only as a directory snippet and was not cross-checked on Dover''s own site; Dover is not among the 29 hinted distributors; Jobify posts list ''Sysmex America, Inc.'' roles in Tel Aviv, which could not be explained.', 'medium', 'Single official Sysmex source (distributor directory), not corroborated by the distributor''s site or a tender document.', 'company', 'partial', 2026, 'confirmed_current', '+81 78 265 0500', '', '1-5-1 Wakinohama-Kaigandori, Chuo-ku, Kobe, Hyogo 651-0073, Japan', '', 'HQ; phone/address from third-party profiles (GlobalData, Plunkett Research); fax +81 78 265 0524; no general email seen');
