INSERT INTO israel_entities (id, manufacturer_id, name, name_he, type, scope, website, phone, email, address, contact_url, evidence_year, status, source) VALUES (105, 59, 'Dover Medical & Scientific Equipment', '', 'distributor', 'Sysmex distributor for Israel per Sysmex Europe''s live distributor directory, which lists ''Dover Medical & Scientific Equipment'', 11 Hamaalot Street, Herzliya, dovermed.co.il (the entry sits beneath a Sysmex UK Ltd. heading, so it may be managed via Sysmex UK); product-line scope not stated (presumably hematology/urinalysis IVD). Dover''s own site returned no Sysmex pages in a domain-restricted search (its indexed content is about da Vinci surgical robotics)', 'https://dovermed.co.il', '+972-9-951-4545', 'contact@dovermed.co.il', '11 Hama''alot Street, Herzliya 46583', '', 2026, 'current', 'https://www.sysmex-europe.com/company/contacts/distributors/');
