INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (60, 'Mindray', 'Mindray; DiaSys Diagnostic Systems (75% owned since 2024); HyTest', 'Shenzhen', 'China', '', 'Public (SZSE ChiNext: 300760)', 1991, 'https://www.mindray.com', 'Clinical / IVD laboratory analyzers', 20000, 2024, 'Approx. 20,000 employees (Mindray 2024 annual report; from memory, not verified this session). Company states subsidiaries in 31 countries.', 'CNY 36.73 billion', 5105, 'FY2024', 'company', 'FY2024 revenue ≈ CNY 36.7 bn (+5%); FY2025 (reported April 2026) was lower after an ~18% H1-2025 decline in domestic sales — exact FY2025 figure not verified this session. Figures from memory of Mindray''s annual reports — verify.', 'reported', 'unclear', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Neither recorded entity could be re-confirmed: Eldan''s live site pages surfaced by a domain-restricted search do not mention Mindray, and the Bepex claim rests on a LinkedIn post. Israeli government procurement notices on mr.gov.il (2025-2026) show Mindray products in active use - Rambam Medical Center bought modules and a nurses'' station for Mindray monitors and issued tender-exemption notice 6506/2026 for Mindray monitor fluid-collection cups, Sheba ran a tender for GE/Philips/Mindray/Welch Allyn monitor accessories, and a Ministry of Health contracts-committee document lists Shenzhen Mindray Bio-Medical among suppliers - but these concern patient monitoring, not IVD, and do not name an Israeli distributor. Hebrew and English distributor searches and mindray.com found no Israeli office or named representative, so the current channel for Mindray''s laboratory analyzers is unclear. Searched ''"Mindray" Israel distributor/נציג/יבואן'', Hebrew ''מיינדריי'', the 29 Israeli distributor domains and eldan.biz alone. Eldan''s own site returned pages offering Mindray hematology analyzers and reagents, which is the only distributor-site evidence; a LinkedIn post says Bepex holds Mindray distribution rights for hospital beds and clinical lighting, and another LinkedIn post reports Mindray monitors in all Sheba ICUs without naming the channel. No ''Mindray Medical Israel'' entity or Mindray office in Israel surfaced, and the Israeli channel for patient monitoring/ultrasound was not established; the Eldan scope beyond hematology is unknown.', 'medium', 'Eldan confirmed only from its own site snippets for the hematology/IVD line; no manufacturer-side confirmation and the rest of the portfolio''s channel is unresolved.', 'company', 'partial', 2026, 'older_evidence_only', '+86 755 8188 8997', '', 'Mindray Building, Keji 12th Road South, High-Tech Industrial Park, Nanshan, Shenzhen, Guangdong 518057, China', '', 'HQ; main phone from third-party directories (not confirmed on mindray.com); official investor-relations contact +86 755 8188 8398, ir@mindray.com (https://www.mindray.com/en/investor-relations/faq); a 2015 release gives Keji 11th Road South');
