INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (61, 'BINDER', 'BINDER Inc. (North America)', 'Tuttlingen', 'Germany', '', 'Private (family-owned)', 1983, 'https://www.binder-world.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 400, 2022, 'Company news item (Sept 2022, opening of Competence Factory II) states 400 employees; aggregators range 159-490 (Datanyze 490, ZoomInfo 201-500, Owler 250-500). ~22,000 units/year made solely in Tuttlingen, sold in 135 countries.', 'USD ~110-133 million (aggregator estimates: Prospeo ~110.5M, ZoomInfo/Datanyze ~133.1M)', 120, 'undated aggregator estimates (c. 2024)', 'estimate', 'No official revenue published; private company. Figure is the midpoint of third-party aggregator estimates, not reported.', 'mixed', 'distributor', '[אימות עדכניות 10/2026] Labotal''s live site still lists BINDER among its represented firms (dedicated Binder page plus the Represented Firms and drying-systems pages), so the relationship is current on the distributor''s side. BINDER''s own distributor locator (binder-world.com) returned nothing in a domain-restricted search, so the manufacturer side is not independently confirmed. No other Israeli BINDER channel surfaced. Labotal''s own site lists the brand among the firms it represents and sells its products in Israel (some Labotal pages are several years old; the manufacturer''s distributor page was not opened).', 'medium', '', 'company', 'verified', 2026, 'confirmed_current', '+49 7462 2005-0', 'info@binder-world.com', 'Im Mittleren Ösch 5, 78532 Tuttlingen, Germany', 'https://www.binder-world.com/int-en/company/locations', 'HQ (BINDER GmbH); phone per SelectScience listing, fax +49 7462 2005-100; email from third-party listing (wirtschaftsforum.de), obfuscated on official page; PO Box: Postfach 102, 78502 Tuttlingen');
