INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (62, 'Memmert', '', 'Schwabach (Bavaria); second plant in Büchenbach', 'Germany', '', 'Private (family-owned)', 1933, 'https://www.memmert.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 550, 2024, 'Memmert job advert (StepStone, c. 2024/25): ''rund 550 Menschen aus etwa 30 Nationen''; older chemie.de profile says >400 at two sites; Prospeo''s 101-200 is an automated estimate.', 'EUR 84.7 million', 93.2, 'FY2024', 'company', 'Figure from Craft.co financial profile (EUR 84.7M revenue, EUR 1.7M net income for 2024), which draws on German register filings; the Bundesanzeiger filing itself was not opened. Older Wirtschaftsforum interview cited ~EUR 55M.', 'mixed', 'distributor', '[אימות עדכניות 10/2026] Medent''s live product-category pages (cooled, CO2 and standard incubators, vacuum and drying ovens) still present Memmert units, so Medent remains a current Israeli channel. On the manufacturer side, Memmert''s live ''Your contact person'' page lists Israel under a Channel Sales Manager (Ilya Rumynskiy, +49 9122 925 223) and in its order-processing group, i.e. Israel is handled by channel sales from Germany through local partners; memmert.com does not name the Israeli distributor in snippets. No other Israeli Memmert channel was found. A search for ''Memmert'' restricted to Israeli lab-distributor domains returned a series of Medent (מדנט מכשור מדעי) product pages that explicitly describe the items as ''made by MEMMERT Germany'' (CO2 incubator INC108ivf, IPP/IPS cooled incubators, VO vacuum ovens, UF/UN drying ovens), so Medent is recorded as an Israeli distributor on the strength of its own site. A .co.il-wide search also found a Memmert UF260 datasheet (2017) hosted on kimron.co.il, which is a possible second reseller but is not recorded as an entity because no product or brand page was seen. Memmert''s own distributor locator (memmert.com) was not searched within the budget, so this is distributor-side evidence only; a Labotal 2026 incubator buyer''s guide mentions Memmert''s IPPeco Peltier models but Labotal is a Binder partner and was not seen offering Memmert.', 'medium', 'Israeli distributor established from the distributor''s own product pages (several, current); no confirmation from Memmert''s side.', 'company', 'verified', 2026, 'confirmed_current', '+49 9122 925-0', 'sales@memmert.com', 'Äußere Rittersbacher Straße 38, 91126 Schwabach, Germany', '', 'HQ (Memmert GmbH + Co. KG); from German-pavilion exhibitor listing and Bayern International database; also info@memmert.com (diedeutscheindustrie.de); fax +49 9122 14585; PO Box Postfach 1720, 91107 Schwabach; US: Memmert USA, Eagle WI, +1 262-594-3941');
