INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (66, 'LAUDA', 'LAUDA', 'Lauda-Königshofen', 'Germany', '', 'Private (family-owned, Wobser family)', 1956, 'https://www.lauda.de', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 600, 2025, 'Company press release (Presseportal, April 2025): ''600 employees today''; 2023 release cited 580 worldwide.', 'EUR ~100 million (group)', 110, 'FY2024', 'company', 'April 2025 company press release: group turnover of ''around 100 million euros'' in 2024. Earlier release reported ~EUR 121M consolidated for 2022; the sources do not explain the difference (rounding or decline).', 'reported', 'distributor', '[אימות עדכניות 10/2026] LAUDA''s own live warranty-participants page names Avni Meshulam & Son Ltd., Haifa, as its authorized sales & service partner for Israel (the same page also shows a LAUDA Ultracool/LAUDA Iberica line against Haifa, apparently a layout artefact), and LAUDA''s locations page lists Israel among countries with representatives, so Avni & Son is upgraded to a confirmed authorised partner. Medent''s live LAUDA category pages re-confirm it as a current laboratory-range channel. Citrine Solutions was not re-checked and is kept as older evidence. Medent''s own site has a ''Lauda - Germany'' manufacturer page describing LAUDA as the global leader in constant-temperature equipment plus a Hebrew product category for LAUDA baths, circulators and chillers, so Medent is the clearest Israeli distributor for the laboratory range. A .co.il-wide search also found Citrine Solutions selling LAUDA Variocool VC 1200, Ultracool UC2 and MGW MS units, and Avni & Son hosting the 2026 LAUDA Ultracool (process chiller) brochure, which suggests an industrial-side partner; both are recorded with caveats because neither page states an authorised-distributor relationship. LAUDA''s own locator (lauda.de) was not searched within the budget.', 'medium', 'Medent established from its own brand page; Citrine and Avni & Son are reseller/brochure-host evidence only; no manufacturer-side confirmation.', 'company', 'verified', 2026, 'confirmed_current', '+49 9343 503-0', 'info@lauda.de', 'Laudaplatz 1, 97922 Lauda-Königshofen, Germany', '', 'HQ (LAUDA DR. R. WOBSER GMBH & CO. KG); official imprint; a directory lists fax +49 9343 503-222');
