INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (67, 'Peter Huber Kältemaschinenbau', 'Huber Kältemaschinenbau, Huber USA', 'Offenburg', 'Germany', '', 'Private (family-owned, Huber family)', 1968, 'https://www.huber-online.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 420, NULL, 'Undated company news page on huber-online.com: ''over 420 people at its headquarters''; a 2017 TOP 100 award listed it in the >200-employee class; job listing gives a 51-500 band. Year not established.', 'EUR ~75 million (trade estimate; private)', 83, '2024 (estimate)', 'estimate', 'Huber (Offenburg) is family-owned and publishes no revenue; order-of-magnitude estimate from headcount (~420) and trade press. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', '[אימות עדכניות 10/2026] S.L. Moran''s live site re-confirms the Huber relationship: it hosts Huber''s 2025/2026 general catalogue (uploaded September 2025) and lists Ministat/Unistat units in its heating/cooling-bath category and Huber on its suppliers page. Huber''s own locations page (huber-online.com) lists subsidiaries only and no Israeli distributor was visible, so the manufacturer-side listing is not confirmed. Master-Cold was not re-checked and stays as a low-confidence older entry. A .co.il-wide search for ''Huber Unistat Ministat'' found S.L. Moran (ש.ל מורן, Jerusalem) hosting the Huber ''Inspired by temperature'' general catalogue 2025/2026 (uploaded September 2025) and listing Huber circulation baths and chillers in its heating/cooling-bath category, and a follow-up search restricted to slmoran.co.il confirmed those pages plus a Huber CS-Chiller brochure, so S.L. Moran is recorded as the Israeli distributor. Master-Cold (master-cold.co.il) lists a Ministat 230 and a used Unistat CC and is recorded as a secondary reseller with low confidence. Huber''s own site (huber-online.com) returned only its generic locations/contact pages with no Israel entry visible, and the earlier distributor-domain search found only a Labotal reactor article mentioning Huber in passing.', 'medium', 'S.L. Moran established from its own site (current catalogue + product category); no confirmation from Huber''s locator; Master-Cold is weak evidence.', 'company', 'verified', 2026, 'confirmed_current', '+49 781 9603-0', 'info@huber-online.com', 'Werner-von-Siemens-Straße 1, 77656 Offenburg, Germany', 'https://huber-online.com/en/company/locations', 'HQ (Peter Huber Kältemaschinenbau SE); email from ARABLAB German-pavilion exhibitor listing; subsidiaries in US, CH, IT, IN, UK listed on locations page');
