INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (68, 'BÜCHI Labortechnik', 'BUCHI, Büchi', 'Flawil (St. Gallen)', 'Switzerland', '', 'Private (family-owned)', 1939, 'https://www.buchi.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 800, 2025, 'Switzerland Global Enterprise (S-GE) success story, Nov 2025: around 800 employees worldwide, about two thirds outside Switzerland; 97% of turnover generated abroad (no absolute revenue given).', 'USD ~204 million (aggregator estimate; other aggregators range from USD 8M to USD 750M)', 204, 'undated aggregator estimate (c. 2024)', 'estimate', 'No official 2024/2025 revenue figure found; aggregator estimates (ZoomInfo, Bitscale) conflict and were ignored.', 'mixed', 'distributor', '[אימות עדכניות 10/2026] Dr. Golik''s live site re-confirms it as the Israeli BUCHI channel with a BUCHI manufacturer page, Rotavapor and laboratory-evaporation pages and a BUCHI Pure chromatography page, plus Kugelrohr and fraction-collector listings, so the scope is wider than evaporation alone. BUCHI''s own ''BUCHI Worldwide'' support page includes Israel in its country filter but the partner name was not visible in the snippet. No other Israeli BUCHI channel surfaced. A search for ''Buchi Rotavapor'' restricted to Israeli distributor domains returned Dr. Golik''s own BUCHI manufacturer page, its ''Dr. Golik - BUCHI - Laboratory Evaporation'' page and a Hebrew Rotavapor product page (noting the R-100 discontinuation and pointing to R-80/R-300), so Dr. Golik (ד"ר גוליק) is recorded as the Israeli distributor. MRC pages in the same results concern MRC''s own-brand rotary evaporators, not BUCHI. BUCHI''s own distributor locator (buchi.com) was not searched within the budget, so whether Dr. Golik also carries BUCHI''s extraction, Kjeldahl, NIR or spray-drying lines is unconfirmed.', 'medium', 'Distributor established from its own dedicated BUCHI pages; manufacturer-side confirmation not obtained.', 'company', 'verified', 2026, 'confirmed_current', '+41 71 394 63 63', '', 'Meierseggstrasse 40, Postfach, 9230 Flawil, Switzerland', '', 'HQ (BÜCHI Labortechnik AG); from third-party profiles (American Pharmaceutical Review, bulkinside, ZoomInfo); fax +41 71 394 64 64; no general email seen');
