INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (72, 'NuAire', 'NuAire Laboratory Equipment; brands: LabGard, In-VitroCell, Glacier, AireGard, NuWind', 'Plymouth, Minnesota', 'USA', 'Kewaunee Scientific (since Nov 2024)', 'Subsidiary of Kewaunee Scientific (public, NASDAQ: KEQU)', 1971, 'https://www.nuaire.com', 'Biosafety cabinets & clean-air equipment', 300, NULL, 'Third-party estimates: PitchBook ~300, Datanyze 267, ZoomInfo 201-500, other directories 114-200. NuAire''s site says it ''supports 350 Minnesota families'' (three facilities in Plymouth and Long Lake, MN, >300,000 sq ft). PitchBook labels ownership ''Acquired/Merged (Operating Subsidiary)'' without naming a parent; no parent found in sources seen.', 'approx. USD 96 million (third-party estimate)', 96, 'n/a (aggregator estimate seen Oct 2026)', 'estimate', 'Datanyze and ZoomInfo both list ~USD 96M; Visual Visitor gives USD 10-50M. No published figure (private company).', 'estimate', 'distributor', '[אימות עדכניות 10/2026] Ormir''s live manufacturers page and biosafety-cabinet page still present NuAire, so Ormir remains the current Israeli channel on the distributor''s side. NuAire''s own site routes sales through local representatives and a service-partner locator without naming the Israeli partner; its NU-240 product page lists an ''Israel Outlet (Type H)'' electrical option, showing the Israeli market is served. Citrine Solutions was not re-checked and stays as older evidence. A .co.il-wide search for ''NuAire biosafety cabinet CO2 incubator'' found Ormir (ormir.co.il) with a NU-5731 CO2 incubator product page and a manufacturers page describing NuAire as a leading provider of biosafety cabinets, laminar flow hoods, CO2 incubators and ULT freezers; a follow-up search restricted to ormir.co.il confirmed further NuAire pages (PharmaGard ES NU-NTE800 isolator, biological safety cabinets), so Ormir is recorded as the Israeli distributor. Citrine Solutions hosts a NuAire AutoFlow CO2-incubator catalogue labelled for its customers and is recorded as a secondary reseller. NuAire''s own site (nuaire.com) only offers a sales-partner locator whose entries are not indexed, so no manufacturer-side confirmation was obtained; the earlier Hebrew and distributor-domain searches had found nothing.', 'medium', 'Ormir established from several of its own NuAire product pages; Citrine from a hosted catalogue only; NuAire''s locator could not be read.', 'company', 'verified', 2026, 'confirmed_current', '+1 763-553-1270', '', '2100 Fernbrook Lane N, Plymouth, MN 55447, USA', '', 'HQ; from third-party listings (labcompare, ZoomInfo/Datanyze); toll-free +1 800-328-3352, fax +1 763-553-0459; no general email seen');
