INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (75, 'Antylia Scientific (ex-Cole-Parmer)', 'formerly Cole-Parmer Instrument Company (renamed 2021); brands: Cole-Parmer, Environmental Express, Jenway, Stuart, Techne, Oakton, Traceable, SPEX, Digi-Sense; Masterflex bioprocessing business sold to Avantor in 2021', 'Vernon Hills, Illinois', 'USA', 'Brookfield Business Partners & CDPQ (since May 2025)', 'Private equity (Brookfield Business Partners / CDPQ; previously GTCR)', 1955, 'https://www.antylia.com', 'Lab distribution & own-brand products', 2000, 2024, 'Roughly 2,000 employees (recalled, unverified).', 'approx. USD 400 million (third-party directory estimate)', 400, 'n/a (directory estimate seen Oct 2026)', 'estimate', 'Bitscale directory lists ~USD 400M revenue (low reliability). Context: Brookfield/CDPQ paid ~USD 1.3-1.34bn for the company (May 2025); the Masterflex business sold to Avantor in 2021 for USD 2.9bn had ~USD 300M revenue and is no longer part of Antylia.', 'estimate', 'distributor', '[אימות עדכניות 10/2026] Medent''s live product pages re-confirm it as an Israeli channel for Antylia''s Stuart brand (stirrers, hotplates, rotary evaporators, rotators, water stills) and add the Jenway brand (6305 UV/Vis spectrophotometer). Cole-Parmer''s own site names no Israeli distributor; its privacy policy only states that Antylia Scientific operates through direct fulfilment and distributors worldwide. The channel for the Cole-Parmer brand itself, Techne and Environmental Express remains unidentified. General search (''Cole-Parmer'' OR ''Antylia'' Israel distributor/נציג/יבואן) returned no Israeli entity and no Israel listing on Antylia/IDEX distributor pages (only Australia/NZ: John Morris; Italy). A search restricted to Israeli distributor domains found Medent (medent.co.il) listing Stuart-brand shakers, heated stirrers and water stills. No Israeli partner found for the Cole-Parmer brand itself, Jenway, Techne or Environmental Express; Masterflex is now Avantor and was not searched. Antylia''s own ''find a distributor'' page was not fetched (fetching blocked). Corporate note seen in snippet: Brookfield and CDPQ completed the acquisition of Antylia Scientific for approximately USD 1.3 billion (CDPQ news release).', 'medium', 'Israeli reseller verified for one brand (Stuart) from the distributor''s own product pages; coverage of other Antylia brands unverified. No official size figures found (only aggregator estimates, ignored).', 'estimate', 'verified', 2026, 'confirmed_current', '+1 800-323-4340', 'sales@antylia.com', '625 East Bunker Court, Vernon Hills, IL 60061, USA', '', 'HQ; toll-free number and email from a Cole-Parmer-to-Antylia rebranding notice in results; older records list +1 847-549-7600; a directory lists UK line +44 1480 272279 (Antylia/Cole-Parmer UK)');
