INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (76, 'Verder Scientific (Retsch, Carbolite Gero, Eltra, Microtrac MRB, QATM)', 'Verder Group scientific division; brands: Retsch, Carbolite Gero, Eltra, Microtrac MRB, QATM, ERWEKA', 'Haan (North Rhine-Westphalia)', 'Germany', 'Verder International B.V. (Verder Group, Vleuten/Utrecht, Netherlands)', 'Subsidiary of Verder Group (private, family-owned)', 1959, 'https://www.verder-scientific.com', 'Elemental & materials analysis', 1300, 2025, 'Verder Scientific division page: ''more than 1,300 employees'' (another passage on the same page says ''over 1,000''); undated company-website figure. Revelio puts the wider Verder International group at ~1,491 (2025).', 'EUR 300+ million', 330, 'undated (company website, accessed 2026)', 'company', 'Division website states ''more than EUR 300 million in sales'' (undated). An older job-board profile cites ~750 employees / EUR 150 million, clearly outdated.', 'reported', 'distributor', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Re-checked on 2026-10-15: a search restricted to the Verder Scientific group sites (retsch.com, carbolite-gero.com, verder-scientific.com, eltra.com, microtrac.com, qatm.com) returned only generic ''contact partners worldwide'' pages with no Israel entry in the snippets. Two searches across mrclab.com and 20 other Israeli distributor domains returned only MRC''s live Carbolite Gero catalogue pages (forced-air, clean-room, solvent-drying and atmosphere ovens, chamber and tube furnaces), so MRC still sells Carbolite Gero in Israel; nothing surfaced for Retsch, Eltra, Microtrac or QATM. MRC''s official versus reseller status is still not stated by either side. General search (''Retsch'' OR ''Carbolite Gero'' OR ''Verder Scientific'' Israel distributor/נציג/יבואן) found no Israeli entity (only Verder Scientific South Africa and US pages). Domain-restricted search found multiple mrclab.com pages selling Carbolite Gero ovens/furnaces; nothing surfaced for Retsch, Eltra, Microtrac or QATM on the Israeli distributor domains. Whether MRC is the official Carbolite Gero distributor or a reseller is not stated in the snippet; Verder''s regional contact pages were not fetched.', 'medium', 'Size from the company''s own website but undated; Israeli presence verified for Carbolite Gero via MRC product pages only; Retsch (the flagship brand) remains unverified in Israel.', 'company', 'partial', 2026, 'confirmed_current', '+49 2104 2333-500', 'info@verder-scientific.com', 'Retsch-Allee 1-5, 42781 Haan, Germany', 'https://www.verder-scientific.com/contact', 'HQ. Official contact page. US subsidiary Verder Scientific Inc.: 11 Penns Trail, Newtown, PA 18940, +1 866-473-8724, info-us@verder-scientific.com.');
