INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (77, 'Yamato Scientific', 'ヤマト科学; originally Sosuke Morikawa & Company (1889); subsidiary Yamato Scientific America (1989)', 'Tokyo (Chuo-ku, Nihonbashi)', 'Japan', '', 'Private', 1889, 'https://www.yamato-scientific.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 600, 2024, 'Roughly 600 employees (recalled, unverified).', 'JPY ~25 billion (trade estimate; private)', 170, 'FY2024 (estimate)', 'estimate', 'Yamato Scientific (Tokyo, founded 1889) is privately held; order-of-magnitude estimate. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Re-checked on 2026-10-15: a search restricted to Yamato''s own domains again returned only the global partners page (yamato-scientific.com/global/) naming S.L. Moran Ltd (Shatner Center bldg 7, Givat Shaul, Jerusalem, +972-74-7029898) as the Israel sales representative, and the search tool again flagged the page as roughly eight years old (c. 2018). A search restricted to slmoran.co.il returned only a 2019/2020 Van der Heijden catalogue and no Yamato content, and a general English/Hebrew search found no Israeli distributor (Agentek appeared only as an unrelated generic hit). The listing therefore rests on a dated page and could not be confirmed as current. A search restricted to Yamato''s own domains returned its global partners page (yamato-scientific.com/global/), whose snippet lists S.L. Moran Ltd, Shatner Center building 7, Givat Shaul, Jerusalem, with a +972 phone number as the Israel representative; the search tool flagged the page as roughly 3,000 days old, so the listing may be stale. A follow-up search restricted to slmoran.co.il returned no Yamato content (only a Van der Heijden catalogue and the about page), and a .co.il-wide search found only a BioFindly directory entry describing Yamato without naming an Israeli agent. S.L. Moran is an active Israeli lab-equipment importer (it hosts 2025 Huber material), so the listing is plausible but unconfirmed from the distributor side.', 'low', 'Manufacturer''s own partner page names the entity, but the page appears old and the distributor''s site shows no Yamato products.', 'estimate', 'partial', 2018, 'older_evidence_only', '+81 3-5548-7101', '', 'Harumi Triton Square Office Tower Y (36F), 1-8-11 Harumi, Chuo-ku, Tokyo 104-6136, Japan', 'https://www.yamato-scientific.com/support/inquiry/', 'HQ. Head office moved to Harumi Triton Square in July 2019 (main fax +81 3-5548-0131); registered head office is 2-2-2 Nihonbashi-Honcho, Chuo-ku, Tokyo 103-0023. International Sales +81 3-5548-7122. No email shown (web inquiry form). Second search used.');
