INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (78, 'Azenta Life Sciences', 'Azenta Life Sciences; formerly Brooks Automation (renamed 2021); brands: GENEWIZ, FluidX, Ziath, 4titude, Limfinity, FreezerPro, Barkey; B Medical Systems (divestiture agreed Dec 2025)', 'Burlington, Massachusetts', 'USA', '', 'Public (NASDAQ: AZTA)', 1978, 'https://www.azenta.com', 'Lab refrigeration & cold storage', 2700, 2025, 'Headcount NOT found in snippets: the FY2025 10-K surfaced but the Human Capital section was not shown; aggregator figures (Revelio ~2,594 Dec-2025; Tracenable ~3,000) ignored.', 'USD 594 million', 594, 'FY2025 (ended 30-Sep-2025)', 'company', 'Azenta press release 21-Nov-2025 and FY2025 10-K: revenue USD 594 million, +4% YoY (+3% organic); Sample Management Solutions USD 325 million (+2%), Multiomics USD 269 million (+6%); net income from continuing ops USD 24.5 million; adjusted EBITDA USD 66 million (11.2% margin).', 'mixed', 'distributor', '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: azenta.com has only a form-based distributor finder and its pages do not name an Israeli partner. HyLabs'' live ''AZENTA - GENOMICS SERVICES'' / ''AZENTA (GENEWIZ)'' pages (research and clinical categories) still offer Azenta/GENEWIZ gene synthesis, cloning, oligo pools, mutagenesis and plasmid prep, and Tamar''s live ''Represented companies'' page lists 4titude as an Azenta Life Sciences (UK) brand; the FluidX part of Tamar''s scope did not surface in this round''s snippets. Both distributor pages are live, so the relationships count as current. General search (''Azenta'' OR ''GENEWIZ'' Israel distributor/נציג/יבואן) returned only Azenta/GENEWIZ''s own pages with no Israel mention. Domain-restricted search found Tamar''s ''Represented companies'' page listing both ''Azenta Life Sciences (United Kingdom)'' and ''4titude (Azenta Life Sciences)'', plus a 4titude automatic roll heat sealer product page. No Israeli channel found for GENEWIZ genomics services (likely ordered directly online) or for automated -80 C / cryogenic sample stores; Azenta''s own where-to-buy page not fetched.', 'medium', 'FY2025 revenue official (10-K/press release); headcount missing. Israeli distributor verified from the distributor''s own represented-companies page for consumables/benchtop instruments; services and large automated stores unverified.', 'estimate', 'verified', 2026, 'confirmed_current', '+1 888-229-3682', '', '200 Summit Drive, Burlington, MA 01803, USA', '', 'HQ. Address from official global-locations page (no phone/email shown there; inquiries via web forms). Phone 888-229-3682 only from third-party directories (Winmo, Weiss Ratings, Seeking Alpha); some aggregators list +1 978-262-2626 instead - unverified.');
