INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (80, 'SPT Labtech', 'formerly TTP Labtech (spun out of TTP Group in 2018); brands: mosquito, dragonfly, firefly, apricot, comPOUND, arktic, chameleon, BioMicroLab', 'Melbourn (Melbourn Science Park), Cambridgeshire', 'UK', 'EQT Private Equity (EQT IX, since 2022)', 'Private equity (EQT)', 1997, 'https://www.sptlabtech.com', 'Liquid handling & lab automation', 500, 2024, 'Roughly 500 employees (recalled, unverified).', 'GBP 51.9 million (FY2023, per Craft aggregator)', 67.5, 'FY2023 (year to Dec-2023)', 'estimate', 'Craft lists GBP 51.9M revenue and GBP 5.9M net income for FY2023 (probably taken from the UK statutory accounts of the Ltd entity, so it may not cover the whole group). Companies House shows accounts filed to 31 Dec 2024 and FY2025 accounts due by 30 Sep 2026; neither could be opened.', 'estimate', 'distributor', '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: SPT Labtech''s live distributors page still lists Agentek (1987) Ltd., Greenwork Yakum Business Park Building A, Yakum 6097200, +972 09-9657000, for Israel, and the SPT Labtech consumables store''s support page says Israel is among the countries served by its distributors. Agentek''s own SPT Labtech page was not re-searched within the budget. No other Israeli channel surfaced. Established from SPT Labtech''s official distributor page, which lists Agentek (1987) Ltd., Greenwork Yakum Business Park, Building A, Yakum, tel. +972 09-9657000 for Israel; Agentek''s own site has a dedicated SPT Labtech representative page (https://agentek.co.il/representative/spt-labtech/) describing the brand''s liquid-handling and sample-prep focus. Both facts come from search-result summaries of those two pages; the pages themselves could not be opened for a verbatim quote, and the Hebrew spelling of Agentek is the company''s standard rendering rather than text seen on the page. No SPT Labtech subsidiary in Israel found.', 'medium', 'Israeli distributor confirmed by both the manufacturer''s distributor page and the distributor''s own page (via search summaries); size figures are aggregator estimates only.', 'estimate', 'verified', 2026, 'confirmed_current', '+44 1223 627555', '', 'Melbourn Science Park, Melbourn, Hertfordshire SG8 6HB, UK', 'https://sptlabtech.com/contact', 'HQ. Official contact page; no general email shown (a legacy discover@ttplabtech.com appears on a third-party profile under the former company name TTP Labtech). CB Insights lists a different number +44 1763 262626.');
