INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (82, 'KERN & SOHN', 'KERN, Kern & Sohn, SAUTER (force measurement brand)', 'Balingen', 'Germany', '', 'Private (family-owned)', 1844, 'https://www.kern-sohn.com', 'Lab balances & weighing', 200, 2023, 'Approx. 200 employees per English Wikipedia (2023 figures); other aggregators give bands of 51-200 / 51-250.', 'EUR 44.4 million', 48.8, 'FY2023', 'company', 'EUR 44.4 million 2023 revenue and >50% equity ratio per English Wikipedia (seen via search snippet); the underlying company report could not be opened this run.', 'reported', 'distributor', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Re-checked on 2026-10-15: kern-sohn.com returned only corporate/product pages and dealer-training pages, with no Israeli dealer named. BDL''s live catalogue pages still list KERN EW-N/EG-N precision balances and a KERN balance bench with granite slab, so BDL continues to resell KERN products; whether it is an authorised dealer is still not stated by either side. No other Israeli channel surfaced. A .co.il-wide search for ''KERN & SOHN balances scales'' found BDL (bdl.co.il) listing KERN EW-N/EG-N precision balances and Kern & Sohn GmbH matrix printers for KERN balances, and a follow-up search restricted to bdl.co.il confirmed those listings; BDL is recorded as an Israeli reseller/distributor, although its catalogue-style site (EUR prices, many European lab brands) suggests an import catalogue rather than an exclusive agency. Searches restricted to kern-sohn.com returned only corporate pages with no Israel dealer entry, and the two distributor-domain searches returned nothing (the first was polluted by ''kernel balancing'' papers). KERN''s own dealer locator could not be read, so other Israeli channels may exist.', 'medium', 'Reseller established from its own product listings; identity of BDL and manufacturer-side confirmation not obtained.', 'company', 'partial', 2026, 'confirmed_current', '+49 7433 9933-0', 'info@kern-sohn.com', 'Ziegelei 1, 72336 Balingen, Germany', '', 'HQ. From ARABLAB German Pavilion exhibitor profile and KERN product manuals; fax +49 7433 9933-149.');
