INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (83, 'A&D Company (A&D HOLON Holdings)', 'A&D Company, Limited; A&D Weighing; A&D Instruments; A&D Engineering; Holon Create', 'Toshima-ku, Tokyo', 'Japan', '', 'Public (TSE: 7745)', 1977, 'https://www.aandd.jp', 'Lab balances & weighing', 2438, 2025, 'Consolidated A&D HOLON Holdings headcount per Simply Wall St (2,438); TipRanks lists 2,471 for an earlier period. A&D HOLON Holdings became the holding company of A&D Company and Holon Create in 2023; balances are made by the A&D Company subsidiary (Measurement & Weighing segment).', 'JPY 69,326 million', 464.5, 'FY ending Mar-2026', 'company', 'Consolidated net sales JPY 69,326 million (+3.3% YoY) per stockanalysis.com / envalith.com / logmi; operating income JPY 9,210 million. Segment net sales: Measurement & Weighing JPY 31,545 million, Medical & Health JPY 26,667 million, Semiconductor-related JPY 11,114 million.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Re-checked on 2026-10-15 with three searches: ''A&D'' Israel distributor restricted to aandd.jp/aandd.com (corporate, regional-affiliate and worldwide-links pages only, no Israel entry); ''A&D'' balance/scale/מאזניים across 22 Israeli distributor and scale-dealer domains (only generic Labotal balance guides and Precisa pages); and a general ''"A&D Company" OR "A&D Weighing" Israel distributor'' search (only US/international retailers). No Israeli distributor, dealer or subsidiary was found. Four approaches found no Israeli entity: ''A&D balance'' and ''A&D Company Japan balances GX GF'' restricted to the Israeli distributor domain list (only generic MRC balance guides), ''A&D Israel distributor'' restricted to aandd.jp (corporate pages only; the global network page''s Israel entry, if any, is not indexed), and two .co.il-wide searches (''A&D analytical balance Japan GX-A HR-A'', ''A&D Weighing'') that returned Labotal/MRC/Ohaus/Precisa balance pages and unrelated hits. The brand name is hard to search (ampersand) and A&D may be sold in Israel through a weighing/industrial-scale importer rather than a lab distributor, or supplied from abroad; no credible lead was seen. Result: none_found after English, Hebrew-domain and manufacturer-site searches.', 'low', 'No Israeli entity found; the negative result may reflect search limitations rather than true absence.', 'company', 'partial', NULL, 'not_found', '+81 3-5391-6132', '', '3-23-14 Higashi-Ikebukuro, Toshima-ku, Tokyo 170-0013, Japan', 'https://aandd.jp/company/contact_us.html', 'HQ. Official contact page; fax +81 3-5391-1566; no email shown (web contact form).');
