INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (91, 'DWK Life Sciences', 'DURAN, WHEATON, KIMBLE, KIMAX; formed from Duran Group, Wheaton Industries and Kimble Chase', 'Mainz (sources also cite Wertheim; US headquarters Millville, New Jersey)', 'Germany', 'One Equity Partners (portfolio company)', 'Private equity (One Equity Partners)', 2017, 'https://www.dwk.com', 'Labware & consumables (plastic & glass)', 1800, 2025, '''Over 1,800 employees worldwide'' per DWK''s own careers page (current); 12 manufacturing sites, presence in 50+ countries (ChromatographyToday profile). Third-party directories give 470-1,900.', 'USD 105.7 million', 106, 'FY2023', 'estimate', 'Preqin database figure (revenue c. USD 105.72M, EBITDA c. USD 11.51M, 2023); scope unclear and probably a single legal entity rather than the whole group. Other third-party estimates range from USD 50-100M (Seamless.AI), USD 101.8M (RocketReach) to USD 350M (Prospeo). No company-published revenue found.', 'mixed', 'distributor', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Re-checked on 2026-10-15: dwk.com''s ''Global Distributors'' locator is location based and no Israeli distributor appears in any snippet. Danyel Biotech''s live SciLabware brand page still presents SciLabware as ''a DWK Life Sciences company'' and lists the Pyrex, Quickfit, MBL, Azlon, Ramboldi and WHEATON lines, so Danyel''s SciLabware/Wheaton channel is current; no Israeli site naming DURAN or KIMBLE surfaced, so the channel for those lines remains unknown. Danyel Biotech''s own brand page ''SciLabware - Danyel Biotech'' presents SciLabware as ''a DWK Life Sciences company'' and lists its 6,000+ products (Pyrex borosilicate and Quickfit jointed glassware, MBL volumetric ware, Azlon plasticware, Wheaton packaging and dropper bottles), so Danyel represents at least DWK''s UK SciLabware/Wheaton range in Israel. Searches for DURAN, Wheaton and Kimble across the 40 Israeli distributor domains and a Hebrew query (''DURAN בקבוקי זכוכית מעבדה יבואן ישראל'') found no Israeli site naming DURAN or KIMBLE, so the channel for those lines (possibly general lab-supply houses or VWR/Thermo catalogues) remains unidentified. DWK''s own site was not searched within the budget.', 'medium', 'Distributor''s own brand page; scope limited to the SciLabware/Wheaton range; manufacturer''s page not seen.', 'company', 'partial', 2026, 'confirmed_current', '+49 9342 802-0', '', 'Otto-Schott-Str. 21, 97877 Wertheim, Germany', 'https://www.dwk.com/request-a-quote', 'HQ (official site labels the Wertheim site as HQ of DWK Life Sciences GmbH). Contact page also gives GmbH address Hattenbergstr. 10, 55122 Mainz, +49 6131 1445 4131; US: 1501 North 10th Street, Millville, NJ, +1 856-825-1100 / 1-800-225-1437; UK (Stoke-on-Trent) +44 1782 444406. All emails masked in results.');
