INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (92, 'Greiner Bio-One', 'Greiner Bio-One International GmbH; VACUETTE, CELLSTAR, Sapphire, µClear; formerly Greiner Labortechnik', 'Kremsmünster', 'Austria', 'Greiner AG', 'Subsidiary of Greiner AG (private, family-owned)', 1963, 'https://www.gbo.com', 'Labware & consumables (plastic & glass)', 2624, 2024, 'Greiner Bio-One division: 29 locations and 2,624 employees in 2024 (Greiner AG 2024 results release). Greiner AG group: 10,242 employees in 2025 (10,318 in 2024). Division headcount for 2025 not found.', 'EUR 637 million', 701, 'FY2025', 'segment', 'Greiner Bio-One division sales c. EUR 637M in 2025, down from EUR 666M in 2024 (+4.5% that year), per Greiner AG financial-year 2025 release; cites regulatory requirements and slower growth in core markets, especially the USA. Greiner Mediscan to be run as an independent division from 2026.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: Greiner Bio-One''s live ''Subsidiaries & distributors'' page lists Danyel Biotech, 8 Hamada - Science Park, 7414002 Rehovot, +972-8-9366066, danyel.co.il, as its Israeli distributor for the Preanalytics, BioScience and CLiP safety IV catheter divisions. This upgrades the earlier distributor-side-only evidence to a manufacturer-side listing. Danyel''s own Greiner page was not re-searched within the budget. Danyel Biotech''s own site has a Greiner Bio-One brand page and lists Greiner among the companies it represents in Israel.', 'medium', '', 'company', 'verified', 2026, 'confirmed_current', '+43 7583 6791-0', 'office@gbo.com', 'Bad Haller Straße 32, 4550 Kremsmünster, Austria', '', 'HQ (Greiner Bio-One International GmbH). Phone/address from official imprint; fax +43 7583 6318; office@gbo.com from the 2022 press kit on gbo.com - verify. North America office Monroe, NC +1 704-261-7800; Netherlands info.nl@gbo.com. Second search used.');
