INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (93, 'SARSTEDT', 'SARSTEDT Group; S-Monovette, Safety-Multifly, Microvette, Salivette', 'Nümbrecht', 'Germany', '', 'Private (family-owned)', 1961, 'https://www.sarstedt.com', 'Labware & consumables (plastic & glass)', 3000, 2025, '''More than 3,000 employees'' per sarstedt.com and the corporate brochure dated Oct 2025 (and Mar 2026 edition); 34 sales organisations and 13 production sites. Revelio Labs counts c. 1,354 for the German KG entity alone.', 'USD 814.7 million', 815, 'undated (database estimate)', 'estimate', 'No company-published revenue found. Datanyze lists USD 814.7M (no year/source); Prospeo estimates USD 480M. Treat as rough third-party estimates.', 'mixed', 'distributor', '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: a search restricted to sarstedt.com returned its sales-organisations and contact pages (30+ own sales organisations plus a distributor network) with no Israel entry in the snippets. Tamar''s live ''Represented companies'' page lists SARSTEDT (Germany, plastic laboratory and medical products) and Tamar''s product pages carry Sarstedt gel-loading tips, reagent/centrifuge tubes and disposable cuvettes, so the channel is current on the distributor side. Tamar Laboratory Supplies'' ''Represented companies'' page lists Sarstedt, and Tamar sells Sarstedt tubes and cuvettes in Israel.', 'medium', '', 'company', 'verified', 2026, 'confirmed_current', '+49 2293 305-0', 'info@sarstedt.com', 'Sarstedtstraße 1, 51588 Nümbrecht, Germany', 'https://sarstedt.com/en/contact', 'HQ. Official contact page; fax +49 2293 305-2470; orders vertrieb@sarstedt.com.');
