INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (95, 'Berthold Technologies', 'Berthold Technologies GmbH & Co. KG; formerly EG&G Berthold / PerkinElmer; Mithras, Tristar, Lumat, NightOWL', 'Bad Wildbad', 'Germany', '', 'Private (family-owned; Berthold family with Hans J. Oberhofer bought it back from PerkinElmer in 2000)', 1949, 'https://www.berthold.com', 'Microplate readers & detection', 360, 2024, '''More than 360 employees'' per the 75-year anniversary message from managing director Marco Gauger on berthold.com; company boilerplate elsewhere says c. 350 worldwide. Subsidiaries in Austria, Belgium, France, UK, Italy, Switzerland and USA.', 'EUR 77 million', 85, 'FY2017', 'company', 'Only figure found: 2017 sales of EUR 77M with 330 employees (EverybodyWiki, secondary source); no newer figure located.', 'mixed', 'distributor', '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: Danyel Biotech''s live ''Berthold Technologies'' brand page still presents Berthold''s bioanalytic line (microplate/multimode readers incl. TriStar2, tube luminometers, NightOWL imaging, gamma counters, HPLC radio detectors). Berthold''s own contacts pages (the process-control contacts page and the company ''worldwide contacts'' page) list Oriontech Engineering, PO Box 3012, 2412901 Akko (contact Aharon Shneiderman) for Israel, recorded here as a new entity; the snippets do not state which Berthold divisions Oriontech covers. The 40-domain sweep returned Danyel Biotech''s own ''Berthold Technologies - Danyel Biotech'' brand page listing Berthold''s Mithras LB 940 (luminescence/BRET/FRET/AlphaScreen/HTRF reader), NightOWL imaging system, TriStar² and Lumat³ luminometers, i.e. Danyel represents Berthold''s bioanalytical line in Israel (Danyel also carries the competing Hidex readers). No other Israeli distributor site mentioned Berthold, and Berthold''s own distributor page was not searched within the budget. Berthold''s radiation-protection and process-control divisions may have a different Israeli channel, which was not investigated.', 'medium', 'Distributor''s own brand page; manufacturer confirmation not seen.', 'company', 'verified', 2026, 'confirmed_current', '+49 7081 177-0', '', 'Calmbacher Straße 22, 75323 Bad Wildbad, Germany', '', 'HQ. Third-party directory listings (Laser Focus World, CHEManager, rapidmicrobiology); fax +49 7081 177-167. No email seen.');
