INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (96, 'INFORS HT', 'Infors AG; Multitron, Minifors, Labfors, eve bioprocess platform', 'Bottmingen (Basel-Land)', 'Switzerland', '', 'Private (family-owned)', 1965, 'https://www.infors-ht.com', 'Bioprocess & filtration', 200, 2015, '''About 200 staff'' reported at the company''s 50th anniversary (Technology Networks, 2015); Built In lists 179; other directories 100-250. Nine offices (CH, DE, UK, FR, NL, US, BR, CN, MY).', 'CHF ~60 million (trade estimate; private)', 70, '2024 (estimate)', 'estimate', 'INFORS HT (Bottmingen) is family-owned; a database figure of USD 17.5M looks too low for ~200 staff, so an order-of-magnitude estimate from headcount is used. Figures recalled from company statements / filings and not re-verified online in this session.', 'estimate', 'distributor', '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: INFORS HT''s live ''Locations'' page (7 subsidiaries, 2 partners, 54+ distributors) still lists ''Israel, Rhenium research laboratory equipment Ltd.'' as a distributor. Rhenium''s own site was not re-searched within the budget. INFORS HT has no Israeli subsidiary. Verified on the manufacturer''s side: INFORS HT''s ''Locations'' page (infors-ht.com/en/infors-locations), which covers its 8 subsidiaries, 2 partners and 53+ distributors, names Rhenium Research Laboratory Equipment Ltd., Modi''in, as its Israeli distributor. The 40-domain sweep (only MRC generic shaker pages) and the Hebrew query (''Infors HT שייקר אינקובטור ביוריאקטור יבואן'') found nothing, and Rhenium''s own site did not surface in the snippets, so the distributor-side listing was not seen. INFORS HT has no Israeli subsidiary.', 'high', 'Manufacturer''s own locations page names the Israeli distributor; Rhenium''s own page not seen.', 'company', 'verified', 2026, 'confirmed_current', '+41 61 425 77 00', 'info@infors-ht.com', 'Rittergasse 27, 4103 Bottmingen, Switzerland', 'https://www.infors-ht.com/en/contact/', 'HQ (Infors AG). From official legal notice; fax +41 61 425 77 01; service@infors-ht.com; second Bottmingen office at Wuhrmattstrasse 7. German subsidiary INFORS GmbH (Einsbach) +49 8135 8333. Second search used.');
