INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (98, 'ELGA LabWater (Veolia)', 'ELGA Veolia; ELGA Process Water (historic); PURELAB, MEDICA, CENTRA', 'High Wycombe (Lane End), Buckinghamshire', 'UK', 'Veolia Water Technologies (Veolia Environnement)', 'Subsidiary of Veolia Water Technologies (Veolia, public, Euronext Paris: VIE)', 1937, 'https://www.elgalabwater.com', 'Lab water purification', 350, 2024, 'ELGA LabWater itself employs roughly 300-400 (recalled, unverified); its parent division Veolia Water Technologies reports >10,300 employees.', 'EUR 2.1 billion', 2310, 'undated (ELGA US site, accessed 2026)', 'parent', 'Parent division (Veolia Water Technologies) revenue per ELGA''s US site; ELGA LabWater alone is not disclosed.', 'reported', 'distributor', '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: a search restricted to elgalabwater.com returned the ''Where to buy ELGA products / Approved Partners'' page, but the snippet did not show the Israel entry this time (ELGA''s trademark page only confirms the ELGA mark is registered in Israel). Lumitron''s live product pages sell ELGA (Elga - Veolia) PURELAB Quest and PURELAB Flex water purification systems, so the channel is current on the distributor side; the manufacturer-side listing seen in the previous round is retained as supporting evidence. ELGA''s own ''Where to buy ELGA products / Approved Partners'' directory (elgalabwater.com and us.elgalabwater.com, page 2) lists Lumitron under Israel with phone 972-52-525-6287 — seen in the search-result excerpt of that page. The Approved Partners page itself and Lumitron''s own website could not be opened to confirm scope (WebFetch DNS failures), and the Hebrew search ''ELGA LabWater ישראל Lumitron'' returned nothing further. Xylem is also described as an ELGA distributor on generic regional pages, but not for Israel.', 'medium', 'Israeli partner comes from ELGA''s official directory (seen via search excerpt only); ELGA-specific size figures are third-party estimates.', 'estimate', 'verified', 2026, 'confirmed_current', '+44 20 3567 7300', '', 'Lane End Business Park, Lane End, High Wycombe, HP14 3BY, UK', 'https://us.elgalabwater.com/contact', 'HQ (UK, Lane End). Fax +44 20 3567 7205. contact_url is the official US-site contact page (UK email obfuscated in results). Only role email seen: Techsupport@elgalabwater.com (technical support). US office Woodridge, IL +1 630-343-5251.');
