INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (99, 'ATS Scientific Products (ex-SP Industries)', 'SP Industries; SP Scientific; ATS Life Sciences Scientific Products; SP VirTis, SP Hull, SP Genevac, SP Bel-Art, SP Wilmad-LabGlass, SP PennTech, FTS Systems, Hotpack', 'Warminster, Pennsylvania', 'USA', 'ATS Corporation', 'Subsidiary of ATS Corporation (public, TSX/NYSE: ATS)', NULL, 'https://www.scientificproducts.com', 'General lab equipment (incubators, ovens, baths, shakers, stirrers)', 700, 2021, 'c. 700 employees across nine manufacturing facilities/locations in the US, UK and Spain at the time ATS agreed to acquire SP Industries (Nov 2021 ATS announcement); no newer division-level figure found.', 'USD 179 million', 179, 'TTM ending Sep-2021', 'company', 'Revenue USD 179M and adjusted EBITDA USD 29M for the twelve months ended 30 Sep 2021 per the ATS acquisition announcement (price c. USD 445M / C$550M; c. 70% North America, c. 73% biopharma & life-science equipment). Some coverage cited c. USD 223M. ATS does not report Scientific Products separately since.', 'reported', 'none_found', 'חיפוש רשת בלבד; דפי ״מפיצים״ של היצרן ואתרי המפיצים לא נפתחו (חסימת רשת). [אימות עדכניות 10/2026] Re-checked on 2026-10-15: a search restricted to scientificproducts.com/spscientific.com returned only brand, product and news pages (Genevac, VirTis, Hull, Bel-Art, FTS, Hotpack, Wilmad) with no Israel entry, and a general English/Hebrew search for Genevac/VirTis/Bel-Art/SP Scientific Israel distributor returned only US/Australian resellers and Bel-Art corporate pages (part of ATS since Dec-2021). No Israeli distributor was found. Searched: ''Genevac'' OR ''VirTis'' OR ''Bel-Art'' OR ''SP Scientific'' Israel distributor/נציג/יבואן; ''SP Scientific''/''VirTis''/''Genevac''/''ATS Scientific Products'' freeze dryer Israel representative ישראל (extended); and the brand names restricted to 18 Israeli distributor domains (no hits). Results only confirmed the brand family (Genevac, VirTis, Hull, Bel-Art under SP / scientificproducts.com, part of ATS since Dec-2021) and distributors elsewhere (LMS Consult Germany, BioPharma Process Systems UK). A used-equipment reseller''s shipping-country list that includes Israel is not evidence of a representative. No Israeli entity found; the manufacturer''s distributor page was not fetched.', 'low', 'No Israeli representative surfaced in three searches; no size research requested or done this round.', 'company', 'partial', NULL, 'not_found', '+1 215-672-7800', '', '935 Mearns Road, Warminster, PA 18974-2811, USA', '', 'HQ. Address from PitchBook; phone from CB Insights / company profile. An older ATS locations page lists Tel +1 267-966-5034, Fax +1 215-674-9880 for the Warminster site (SP Industries). Only email seen is parent ATS general info@atsautomation.com (listed under ATS Life Sciences Chicago, not Warminster).');
