INSERT INTO manufacturers (id, name, aka, hq_city, hq_country, parent, ownership, founded, website, category, employees, employees_year, employees_note, revenue_original, revenue_usd_m, revenue_year, revenue_scope, revenue_note, size_basis, israel_presence, israel_note, confidence, confidence_note, employees_scope, israel_check, israel_evidence_year, israel_current, contact_phone, contact_email, contact_address, contact_url, contact_note) VALUES (100, 'RADWAG', 'RADWAG Wagi Elektroniczne; Radwag Balances and Scales', 'Radom', 'Poland', '', 'Private (family-owned)', 1984, 'https://radwag.com', 'Lab balances & weighing', 500, 2024, '''Nearly 500 people'' per RADWAG''s 40-years company profile; the company''s English ''about us'' page lists 403 employees and a 2017-era presentation says 400+ incl. 100 in R&D.', 'PLN 100 million', 26, 'FY2017', 'company', 'Sales value of c. PLN 100M in 2017 per a presentation by founder Witold Lewandowski (saippw.pl); converted at c. USD 0.26/PLN. No newer figure found; KRS filings would give current numbers.', 'mixed', 'distributor', '[אימות עדכניות 10/2026] Re-checked on 2026-10-15: RADWAG''s live contact page lists three Israeli dealers: Newtech Ayalon Ltd (12 Hacharoshet Street, Kfar Saba, weighing.co.il), MRC (mrclab.com, +972 phone) and Lumitron Ltd. (17 Hamefalsim St., zip 49130, +972 732000773, lumitron.co.il); the scraped layout did not tie every name cleanly to its country, but the addresses are Israeli. Lumitron''s live Radwag brand page (MYA 5Y microbalance, AS.X7/AS.X2 analytical balances, WTC 2000 precision balance) confirms its channel from the distributor side; Newtech Ayalon and MRC are added as new entities from the manufacturer''s listing only. General search (''Radwag'' balances Israel distributor/נציג/יבואן) returned only Radwag''s own dealer-zone pages (200+ distributors worldwide, no Israel listing visible). Domain-restricted search found Lumitron''s dedicated Radwag brand page, its ''Our brands'' page and a hosted RADWAG WTC 2000 data sheet. MRC (mrclab.com) balance pages also surfaced in that search but the snippet did not show Radwag branding, so MRC is not recorded.', 'medium', 'Israeli distributor verified from the distributor''s own brand page; manufacturer-side confirmation (Radwag dealer list) not seen. No size research requested this round.', 'company', 'verified', 2026, 'confirmed_current', '+48 48 386 60 00', 'office@radwag.com', 'Toruńska 5, 26-600 Radom, Poland', 'https://radwag.com/en/nasze-biura,2,5', 'HQ. From official offices/contact pages; fax +48 48 385 00 10; export enquiries export@radwag.com.');
